let OperatorsListComponent = class OperatorsListComponent {
  constructor(wellnessCrsService, swalService, router, utility) {
    this.wellnessCrsService = wellnessCrsService;
    this.swalService = swalService;
    this.router = router;
    this.utility = utility;
    this.showFilters = false;
    this.operatorsList = [];
    this.filteredOperatorsList = [];
    // FULL TEXT SEARCH
    this.searchText = "";
    // FILTERS
    this.filterData = {
      operator_name: "",
      company_name: "",
      email: "",
      city: ""
    };
  }
  ngOnInit() {
    this.getAllOperators();
  }
  // ========================= GET ALL =========================
  // ========================= GET ALL OPERATORS =========================
  getAllOperators() {
    const data = {
      topic: "listHeliOperator"
    };
    this.wellnessCrsService.fetch(data).subscribe(resp => {
      if (resp.Status === true && (resp.statusCode === 200 || resp.statusCode === 201)) {
        this.operatorsList = resp.data || [];
        this.filteredOperatorsList = resp.data || [];
      } else {
        this.operatorsList = [];
        this.filteredOperatorsList = [];
      }
    }, err => {
      this.swalService.alert.error(err["error"]["Message"]);
    });
  }
  // ========================= STATUS CHANGE =========================
  onStatusChange(event, item) {
    const status = event.target.checked ? 1 : 0;
    const data = {
      id: item.id,
      status: status
    };
    this.wellnessCrsService.create({
      topic: "updateHelioperatorStatus",
      0: data
    }).subscribe(resp => {
      if (resp.Status === true && (resp.statusCode === 200 || resp.statusCode === 201)) {
        this.swalService.alert.success("Operator status updated successfully.");
        this.getAllOperators();
      } else {
        this.swalService.alert.error("Failed to update operator status.");
      }
    }, err => {
      this.swalService.alert.error(err["error"]["Message"]);
    });
  }
  // ========================= DELETE =========================
  onDelete(id) {
    this.swalService.alert.delete(action => {
      if (action) {
        const data = {
          id: id
        };
        this.wellnessCrsService.create({
          topic: "deleteHeliOperator",
          0: data
        }).subscribe(response => {
          if (response.statusCode == 200 || response.statusCode == 201) {
            this.swalService.alert.success("Operator deleted successfully.");
            this.getAllOperators();
          }
        }, err => {
          this.swalService.alert.error(err["error"]["Message"]);
        });
      }
    });
  }
  // ========================= FULL TEXT SEARCH =========================
  filterOperators() {
    const search = this.searchText.toLowerCase().trim();
    if (!search) {
      this.filteredOperatorsList = [...this.operatorsList];
      return;
    }
    this.filteredOperatorsList = this.operatorsList.filter(item => {
      return (item.operator_name || "").toLowerCase().includes(search) || (item.company_name || "").toLowerCase().includes(search) || (item.email || "").toLowerCase().includes(search) || (item.city_name || "").toLowerCase().includes(search) || (item.contact_person || "").toLowerCase().includes(search) || (item.contact_no || "").toLowerCase().includes(search);
    });
  }
  // ========================= FILTER SEARCH =========================
  onSearch() {
    this.filteredOperatorsList = this.operatorsList.filter(item => {
      return (!this.filterData.operator_name || (item.operator_name || "").toLowerCase().includes(this.filterData.operator_name.toLowerCase())) && (!this.filterData.company_name || (item.company_name || "").toLowerCase().includes(this.filterData.company_name.toLowerCase())) && (!this.filterData.email || (item.email || "").toLowerCase().includes(this.filterData.email.toLowerCase())) && (!this.filterData.city || (item.city_name || "").toLowerCase().includes(this.filterData.city.toLowerCase()));
    });
  }
  // ========================= RESET FILTER =========================
  resetFilters() {
    this.filterData = {
      operator_name: "",
      company_name: "",
      email: "",
      city: ""
    };
    this.searchText = "";
    this.filteredOperatorsList = [...this.operatorsList];
  }
  // ========================= UPDATE =========================
  onUpdate(data) {
    this.wellnessCrsService.getEditData.next(data);
    this.wellnessCrsService.tabSwitch$.next('add_operators');
  }
  exportExcel() {
    const fileToExport = this.filteredOperatorsList.map((item, index) => {
      return {
        "Sl No": index + 1,
        "Status": item.status === 1 || item.status === "1" ? "Active" : "Inactive",
        "Operator Name": item.operator_name || "-",
        "Company Name": item.company_name || "-",
        "DGCA License Number": item.dgpa_licno || "-",
        "Contact Person": item.contact_person || "-",
        "Contact Number": item.contact_no || "-",
        "Email": item.email || "-",
        "Office Address": item.office_addr || "-",
        "City": item.city_name || item.city || "-",
        "State": item.state_name || item.state || "-",
        "Country": item.country_name || item.country || "-",
        "GST Number": item.gst_no || "-",
        "KYC Document": item.kyc_doc ? item.kyc_doc : "-"
      };
    });
    const columnWidths = [{
      wch: 8
    }, {
      wch: 10
    }, {
      wch: 25
    }, {
      wch: 25
    }, {
      wch: 20
    }, {
      wch: 20
    }, {
      wch: 15
    }, {
      wch: 25
    }, {
      wch: 30
    }, {
      wch: 15
    }, {
      wch: 15
    }, {
      wch: 15
    }, {
      wch: 15
    }, {
      wch: 25
    } // KYC
    ];

    this.utility.exportToExcel(fileToExport, 'Heli Operator List', columnWidths);
  }
};
