let SchedulesListComponent = class SchedulesListComponent {
  constructor(heliCrsService, swalService, router, utility) {
    this.heliCrsService = heliCrsService;
    this.swalService = swalService;
    this.router = router;
    this.utility = utility;
    // ================= LIST =================
    this.schedulesList = [];
    this.filteredList = [];
    // ================= SEARCH =================
    this.searchTerm = "";
    this.searchData = {
      operator_name: "",
      route: "",
      helicopter_number: ""
    };
  }
  ngOnInit() {
    this.getAllSchedules();
  }
  // ================= GET ALL =================
  getAllSchedules() {
    const data = {
      topic: "listHeliSchedule"
    };
    this.heliCrsService.fetch(data).subscribe(resp => {
      if (resp.Status === true && (resp.statusCode === 200 || resp.statusCode === 201)) {
        this.schedulesList = resp.data || [];
        this.filteredList = [...this.schedulesList];
      } else {
        this.schedulesList = [];
        this.filteredList = [];
      }
    }, err => {
      this.swalService.alert.error(err["error"]["Message"]);
    });
  }
  // ================= FULL TEXT SEARCH =================
  filterList() {
    const search = this.searchTerm.toLowerCase().trim();
    if (!search) {
      this.filteredList = [...this.schedulesList];
      return;
    }
    this.filteredList = this.schedulesList.filter(item => {
      return (item.operator_name || "").toLowerCase().includes(search) || (item.route || "").toLowerCase().includes(search) || (item.helicopter_model || "").toLowerCase().includes(search) || (item.helicopter_type || "").toLowerCase().includes(search) || (item.travel_date || "").toLowerCase().includes(search);
    });
  }
  // ================= SEARCH FILTER =================
  search() {
    this.filteredList = this.schedulesList.filter(item => {
      return (!this.searchData.operator_name || (item.operator_name || "").toLowerCase().includes(this.searchData.operator_name.toLowerCase())) && (!this.searchData.route || (item.route || "").toLowerCase().includes(this.searchData.route.toLowerCase())) && (!this.searchData.helicopter_number || (item.helicopter_model || "").toLowerCase().includes(this.searchData.helicopter_number.toLowerCase()));
    });
  }
  // ================= RESET =================
  reset() {
    this.searchData = {
      operator_name: "",
      route: "",
      helicopter_number: ""
    };
    this.searchTerm = "";
    this.filteredList = [...this.schedulesList];
  }
  // ================= STATUS UPDATE =================
  updateStatus(item) {
    const data = {
      id: item.id,
      status: item.status ? 1 : 0
    };
    this.heliCrsService.create({
      topic: "updateHeliScheduleStatus",
      0: data
    }).subscribe(resp => {
      if (resp.Status === true && (resp.statusCode === 200 || resp.statusCode === 201)) {
        this.swalService.alert.success("Schedule status updated successfully.");
      } else {
        this.swalService.alert.error("Failed to update status.");
      }
    }, err => {
      this.swalService.alert.error(err["error"]["Message"]);
    });
  }
  // ================= DELETE =================
  delete(item) {
    this.swalService.alert.delete(action => {
      if (action) {
        this.heliCrsService.create({
          topic: "deleteHeliSchedule",
          0: {
            id: item.id
          }
        }).subscribe(resp => {
          if (resp.statusCode === 200 || resp.statusCode === 201) {
            this.swalService.alert.success("Schedule deleted successfully.");
            this.getAllSchedules();
          }
        }, err => {
          this.swalService.alert.error(err["error"]["Message"]);
        });
      }
    });
  }
  // ================= EDIT =================
  edit(item) {
    this.heliCrsService.getEditData.next(item);
    this.heliCrsService.tabSwitch$.next('add_schedules');
  }
  exportExcel() {
    const fileToExport = this.filteredList.map((item, index) => {
      return {
        "Sl No": index + 1,
        "Status": item.status === 1 || item.status === '1' ? 'Active' : 'Inactive',
        "Operator Name": item.operator_name,
        "Route": item.route,
        "Travel Date": item.travel_date,
        "Departure Time": item.departure_time,
        "Arrival Time": item.arrival_time,
        "Duration (mins)": item.duration,
        "Helicopter Type": item.helicopter_type,
        "Helicopter Model": item.helicopter_model,
        "Total Seats": item.total_seats,
        "Available Seats": item.available_seats,
        "Blocked Seats": item.blocked_seats,
        "Baggage Allowance": item.baggage_allowance,
        "Weight Limit": item.weight_limit,
        "Cancellation Policy": item.cancellation_policy
      };
    });
    const columnWidths = [{
      wch: 6
    }, {
      wch: 10
    }, {
      wch: 20
    }, {
      wch: 15
    }, {
      wch: 15
    }, {
      wch: 15
    }, {
      wch: 15
    }, {
      wch: 12
    }, {
      wch: 18
    }, {
      wch: 18
    }, {
      wch: 10
    }, {
      wch: 10
    }, {
      wch: 10
    }, {
      wch: 18
    }, {
      wch: 12
    }, {
      wch: 25
    } // Cancellation
    ];

    this.utility.exportToExcel(fileToExport, 'Helicopter Schedule List', columnWidths);
  }
};
