let HelipadsListComponent = class HelipadsListComponent {
  constructor(heliCrsService, swalService, router, utility) {
    this.heliCrsService = heliCrsService;
    this.swalService = swalService;
    this.router = router;
    this.utility = utility;
    this.showFilters = false;
    this.helipadList = [];
    this.filteredHelipadList = [];
    // FULL SEARCH
    this.searchText = "";
    // FILTERS
    this.filterData = {
      helipad_name: "",
      helipad_code: "",
      city: "",
      state: ""
    };
  }
  ngOnInit() {
    this.getAllHelipads();
  }
  // ========================= GET ALL =========================
  getAllHelipads() {
    const data = {
      topic: "listHeliPad"
    };
    this.heliCrsService.fetch(data).subscribe(resp => {
      if (resp.Status === true && (resp.statusCode === 200 || resp.statusCode === 201)) {
        this.helipadList = resp.data || [];
        this.filteredHelipadList = resp.data || [];
      } else {
        this.helipadList = [];
        this.filteredHelipadList = [];
      }
    }, err => {
      this.swalService.alert.error(err["error"]["Message"]);
    });
  }
  // ========================= STATUS CHANGE =========================
  onStatusChange(event, item) {
    const status = event.target.checked ? 1 : 0;
    const data = {
      id: item.id,
      status: status
    };
    this.heliCrsService.create({
      topic: "updateHelipadStatus",
      0: data
    }).subscribe(resp => {
      if (resp.Status === true && (resp.statusCode === 200 || resp.statusCode === 201)) {
        this.swalService.alert.success("Helipad status updated successfully.");
        this.getAllHelipads();
      } else {
        this.swalService.alert.error("Failed to update helipad status.");
      }
    }, err => {
      this.swalService.alert.error(err["error"]["Message"]);
    });
  }
  // ========================= DELETE =========================
  onDelete(id) {
    this.swalService.alert.delete(action => {
      if (action) {
        const data = {
          id: id
        };
        this.heliCrsService.create({
          topic: "deleteHelipad",
          0: data
        }).subscribe(response => {
          if (response.statusCode == 200 || response.statusCode == 201) {
            this.swalService.alert.success("Helipad deleted successfully.");
            this.getAllHelipads();
          }
        }, err => {
          this.swalService.alert.error(err["error"]["Message"]);
        });
      }
    });
  }
  // ========================= FULL SEARCH =========================
  filterHelipads() {
    const search = this.searchText.toLowerCase().trim();
    if (!search) {
      this.filteredHelipadList = [...this.helipadList];
      return;
    }
    this.filteredHelipadList = this.helipadList.filter(item => {
      return (item.helipad_name || "").toLowerCase().includes(search) || (item.helipad_code || "").toLowerCase().includes(search) || (item.city_name || "").toLowerCase().includes(search) || (item.state_name || "").toLowerCase().includes(search) || (item.country_name || "").toLowerCase().includes(search) || (item.map_location || "").toLowerCase().includes(search);
    });
  }
  // ========================= FILTER SEARCH =========================
  onSearch() {
    this.filteredHelipadList = this.helipadList.filter(item => {
      return (!this.filterData.helipad_name || (item.helipad_name || "").toLowerCase().includes(this.filterData.helipad_name.toLowerCase())) && (!this.filterData.helipad_code || (item.helipad_code || "").toLowerCase().includes(this.filterData.helipad_code.toLowerCase())) && (!this.filterData.city || (item.city_name || "").toLowerCase().includes(this.filterData.city.toLowerCase())) && (!this.filterData.state || (item.state_name || "").toLowerCase().includes(this.filterData.state.toLowerCase()));
    });
  }
  // ========================= RESET FILTER =========================
  resetFilters() {
    this.filterData = {
      helipad_name: "",
      helipad_code: "",
      city: "",
      state: ""
    };
    this.searchText = "";
    this.filteredHelipadList = [...this.helipadList];
  }
  // ========================= UPDATE =========================
  onUpdate(data) {
    console.log(data, "yvugtyg");
    this.heliCrsService.getEditData.next(data);
    this.heliCrsService.tabSwitch$.next('add_helipads');
  }
  exportExcel() {
    const fileToExport = this.filteredHelipadList.map((item, index) => {
      return {
        "Sl No": index + 1,
        "Status": item.status === 1 || item.status === '1' ? 'Active' : 'Inactive',
        "Helipad Name": item.helipad_name,
        "City": item.city_name || item.city,
        "State": item.state_name || item.state,
        "Country": item.country_name || item.country,
        "Map Location": item.map_location,
        "Latitude": item.latitude,
        "Longitude": item.longitude,
        "Helipad Code": item.helipad_code,
        "Description": item.description
      };
    });
    const columnWidths = [{
      wch: 6
    }, {
      wch: 10
    }, {
      wch: 25
    }, {
      wch: 18
    }, {
      wch: 18
    }, {
      wch: 18
    }, {
      wch: 25
    }, {
      wch: 12
    }, {
      wch: 12
    }, {
      wch: 15
    }, {
      wch: 30
    } // Description
    ];

    this.utility.exportToExcel(fileToExport, 'Helipads List', columnWidths);
  }
};
