  getCurrencyNameById(id) {
    // Ensure that the id is treated as a number for comparison
    const numericId = String(id);
    const currency = this.currencyList.find(item => item.currency === numericId);
    return currency ? currency.currency : ''; // Return the currency name
  }

  formatTime(isoTime) {
    const date = new Date(isoTime);
    let hours = date.getHours();
    const minutes = date.getMinutes();
    // Determine AM or PM
    const ampm = hours >= 12 ? 'PM' : 'AM';
    // Convert hours to 12-hour format
    hours = hours % 12;
    hours = hours ? hours : 12; // the hour '0' should be '12'
    // Format minutes as 'MM'
    const formattedMinutes = minutes.toString().padStart(2, '0');
    // Return the formatted time string in 'HH:MM AM/PM' format
    return `${hours}:${formattedMinutes} ${ampm}`;
  }
  mapInitializer() {
    if (!this.gmap) return;
    this.mapOptions = {
      center: this.center,
      zoom: 10,
      mapTypeId: google.maps.MapTypeId.ROADMAP
    };
    this.map = new google.maps.Map(this.gmap.nativeElement, this.mapOptions);
    this.placeMarker();
    this.initializeSearchBox();
  }
  placeMarker() {
    this.marker = new google.maps.Marker({
      position: this.center,
      map: this.map
    });
    this.map.addListener('click', event => {
      if (event.latLng) {
        this.marker.setPosition(event.latLng);
        this.hotelForm.get('latitude').setValue(event.latLng.lat());
        this.hotelForm.get('longitude').setValue(event.latLng.lng());
        // Fetch the correct timezone from Google API
        this.getTimezoneOffset(event.latLng.lat(), event.latLng.lng());
        // Get address from coordinates
        this.getAddress(event.latLng);
      }
    });
    this.marker.addListener('dblclick', () => {
      this.map.setZoom(12);
      this.map.setCenter(this.marker.getPosition());
    });
  }
  initializeSearchBox() {
    const input = this.searchInput.nativeElement;
    const options = {
      types: ['lodging'],
      componentRestrictions: {
        country: 'in'
      } // restrict to India
    };

    const autocomplete = new google.maps.places.Autocomplete(input, options);
    // 🔥 STRICT CITY BOUNDING
    if (this.selectedCityName) {
      const geocoder = new google.maps.Geocoder();
      geocoder.geocode({
        address: this.selectedCityName
      }, (results, status) => {
        if (status === 'OK' && results[0]) {
          const bounds = results[0].geometry.viewport;
          autocomplete.setBounds(bounds);
          autocomplete.setOptions({
            strictBounds: true
          }); // ✅ VERY IMPORTANT
        }
      });
    }

    autocomplete.addListener('place_changed', () => {
      const place = autocomplete.getPlace();
      if (!place.geometry || !place.geometry.location) {
        this.swalService.alert.oops("Invalid location");
        return;
      }
      if (!this.isPlaceInSelectedCity(place)) {
        this.swalService.alert.oops(`Please select hotel only in ${this.selectedCityName}`);
        input.value = '';
        return;
      }
      const location = place.geometry.location;
      // Move map
      this.map.setCenter(location);
      this.marker.setPosition(location);
      // Fill form
      this.hotelForm.get('latitude').setValue(location.lat());
      this.hotelForm.get('longitude').setValue(location.lng());
      this.hotelForm.get('address').setValue(place.formatted_address);
      // Optional: autofill hotel name
      this.hotelForm.get('hotel_name').setValue(place.name);
      this.getTimezoneOffset(location.lat(), location.lng());
    });
  }
  isPlaceInSelectedCity(place) {
    if (!this.selectedCityName) {
      return true;
    }
    const selectedCity = this.normalizeLocationName(this.selectedCityName);
    const cityTypes = ['locality', 'administrative_area_level_2', 'administrative_area_level_3'];
    const cityNames = (place.address_components || []).filter(component => component.types.some(type => cityTypes.includes(type))).reduce((names, component) => {
      names.push(component.long_name, component.short_name);
      return names;
    }, []).map(name => this.normalizeLocationName(name)).filter(Boolean);
    if (cityNames.length) {
      return cityNames.some(cityName => cityName === selectedCity || cityName.includes(selectedCity) || selectedCity.includes(cityName));
    }
    const address = this.normalizeLocationName(place.formatted_address || '');
    return !address || address.includes(selectedCity);
  }
  normalizeLocationName(value) {
    return (value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  }
  getAddress(latLng) {
    this.geocoder = new google.maps.Geocoder();
    this.geocoder.geocode({
      location: latLng
    }, (results, status) => {
      if (status === google.maps.GeocoderStatus.OK) {
        if (results[0]) {
          this.hotelForm.get('address').setValue(results[0].formatted_address);
        } else {
          console.error('No results found');
        }
      } else {
        console.error(`Geocoder failed due to: ${status}`);
      }
    });
  }
