  sortData(sort) {
    const data = filterArray.length ? filterArray : [...respDataCopy];
    if (!sort.active || sort.direction === '') {
      this.respData = data;
      return;
    }
    this.respData = data.sort((a, b) => {
      const isAsc = sort.direction === 'asc';
      switch (sort.active) {
        case 'hotel_name':
          return this.utility.compare('' + a.hotel_name, '' + b.hotel_name, isAsc);
        case 'star_rating':
          return this.utility.compare('' + a.star_rating, '' + b.star_rating, isAsc);
        case 'city':
          return this.utility.compare('' + a.core_city_id, '' + b.core_city_id, isAsc);
        case 'country':
          return this.utility.compare('' + a.core_country_id, '' + b.core_country_id, isAsc);
        case 'city_code':
          return this.utility.compare('' + a.city_code, '' + b.city_code, isAsc);
        case 'address':
          return this.utility.compare('' + a.address, '' + b.address, isAsc);
        case 'phone_number':
          return this.utility.compare('' + a.phone_number, '' + b.phone_number, isAsc);
        case 'email':
          return this.utility.compare('' + a.email, '' + b.email, isAsc);
        default:
          return 0;
      }
    });
  }
