    payload['topic'] = 'updateCarAmenities';
    console.log('Payload:', payload); // ✅ CHECK THIS
    this.hotelCrsService.update(payload).subscribe(resp => {
      if (resp.statusCode == 201) {
        this.swalService.alert.update();
      } else {
        this.swalService.alert.oops();
      }
    }, () => {
      this.swalService.alert.oops();
    });
