  listStates(country_code) {
    const payload = {
      country_code
    };
    this.apiHandlerService.apiHandler('registerState', 'POST', '', '', payload).subscribe(res => {
      if (res.data) {
        this.registerStates = res.data;
        console.log('States List:', this.registerStates); // Debugging
        // ✅ Trigger change detection
        this.cdr.markForCheck();
      } else {
        this.errorMessage = res.data.msg;
        this.registerStates = []; // Ensure list is cleared on error
      }
    });
  }

  listCities() {
    this.apiHandlerService.apiHandler('registerCity', 'POST', '', '', {}).subscribe(res => {
      if (res.data) {
        this.registerCities = res.data;
      } else {
        this.errorMessage = res.data.msg;
      }
    });
  }
  onCountryChange(event) {
    const countryCode = event.target.value;
    console.log('Selected Country Code:', countryCode); // Debugging
    if (countryCode) {
      this.listStates(countryCode); // Fetch states based on selected country
    }
    // Reset state selection when country changes
    this.registerForm.controls['state'].setValue('');
    this.filteredCities = [];
  }
  onStateChange(event) {
    const stateId = event.target.value;
    this.filteredCities = this.registerCities.filter(city => city.state_id == stateId);
    this.registerForm.controls['city'].setValue('');
  }
  filterCities(searchTerm) {
    const stateId = this.registerForm.controls['state'].value;
    if (stateId) {
      this.filteredCities = this.registerCities.filter(city => city.state_id == stateId && city.name.toLowerCase().includes(searchTerm.toLowerCase()));
    }
  }
  getCurrencyList() {
    this.apiHandlerService.apiHandler('hotelCurrencyConverison', 'POST', '', '', {}).subscribe(resp => {
      if (resp.Status && resp.data) {
        this.currencyList = resp.data.filter(t => t.status == 1);
      }
    }, err => {
      console.log(err.error);
    });
  }
  listCountries() {
    return new Promise(resolve => {
      this.apiHandlerService.apiHandler('registerCountry', 'POST', '', '', {}).subscribe(res => {
        if (res.data) {
          this.registerCountries = res.data;
        }
        resolve();
      });
    });
  }
  getTitleList() {
    this.subSunk.sink = this.userManagementService.fetchTitleList().subscribe(resp => {
      if (resp.statusCode == 200 || resp.statusCode == 201) {
        this.userTitleList = resp.data.length ? resp.data.filter(item => item.pax_type === 'ADULT') : [];
      } else {
        this.swalService.alert.oops();
      }
    }, err => {
      console.error(err);
      this.swalService.alert.oops();
    });
  }
  getFlightList(moduleType) {
    return new Promise((resolve, reject) => {
      this.subSunk.sink = this.apiHandlerService.apiHandler("manageApiList", "post", {}, {}, {
        module_type: moduleType
      }).subscribe(resp => {
        if (resp.statusCode == 200 || resp.statusCode == 201) {
          this.noData = false;
          this.respData = resp.data || [];
          resolve(this.respData);
        } else {
          this.noData = true;
          this.swalService.alert.error(resp.msg || "");
          reject(resp.msg || "Error fetching flight list");
        }
      }, err => {
        this.swalService.alert.oops(err.msg || "");
        reject(err.msg || "Error fetching flight list");
      });
    });
  }
  getTypeList() {
    this.subSunk.sink = this.userManagementService.getUserTypeList().subscribe(resp => {
      if (resp.statusCode == 200 || resp.statusCode == 201) {
        this.userTypeList = resp.data.length ? resp.data : this.userManagementService.isDevelopement;
      } else {
        this.swalService.alert.oops();
      }
    }, err => {
      console.error(err);
      this.swalService.alert.oops();
    });
  }
