module.exports = "<div class=\"header-dots\">\n  <div class=\"btn-group\" ngbDropdown autoClose=\"outside\" placement=\"bottom\">\n\n    <button\n      type=\"button\"\n      class=\"btn btn-link p-0 mr-2\"\n      ngbDropdownToggle\n      (click)=\"viewNotifications()\">\n\n      <span>\n        <div class=\"icon-wrapper icon-wrapper-alt rounded-circle\">\n          <img [src]=\"bellIcon\" alt=\"bell\" />\n          <sup class=\"notification-count text-danger\">{{activationCount}}</sup>\n          <div class=\"badge badge-dot badge-dot-sm\">Notifications</div>\n        </div>\n      </span>\n\n    </button>\n\n    <div class=\"dropdown-menu-xl\" ngbDropdownMenu>\n\n      <div class=\"dropdown-menu-header mb-0\">\n        <div class=\"dropdown-menu-header-inner bg-primary\">\n          <div class=\"menu-header-image opacity-1 dd-header-bg-2\"></div>\n          <div class=\"menu-header-content\" style=\"color: #fff;\">\n            <h5 class=\"menu-header-title\">Notifications</h5>\n            <h6 class=\"menu-header-subtitle\">\n              You have <b>{{activationCount}}</b> unread messages\n            </h6>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card-tabbed-header\">\n\n        <ul\n          ngbNav\n          #notificationNav=\"ngbNav\"\n          class=\"nav-tabs tabs-animated custom_tab nav-justified\">\n\n          <li [ngbNavItem]=\"1\">\n            <a ngbNavLink>Events</a>\n\n            <ng-template ngbNavContent>\n\n              <div *ngIf=\"respData && respData.length > 0; else noNotifications\"\n                   class=\"scroll-gradient\">\n\n                <div class=\"scroll-area-sm shadow-overflow\">\n                  <perfect-scrollbar [autoPropagation]=\"true\">\n\n                    <div class=\"vertical-without-time vertical-timeline vertical-timeline--animate vertical-timeline--one-column\">\n\n                      <div\n                        *ngFor=\"let notifications of respData | slice:0:3; let i = index\"\n                        class=\"vertical-timeline-item vertical-timeline-element\">\n\n                        <div>\n                          <span class=\"vertical-timeline-element-icon bounce-in\">\n                            <i class=\"badge badge-dot badge-dot-xl badge-success\"></i>\n                          </span>\n\n                          <div\n                            class=\"vertical-timeline-element-content bounce-in\"\n                            [ngStyle]=\"{\n                              'color': notifications.viewed_datetime == '' ? '#000' : '#c4bbbb'\n                            }\">\n\n                            <h4\n                              class=\"timeline-title\"\n                              [innerHTML]=\"notifications['event_title']\">\n                            </h4>\n\n                            <p>\n                              <span\n                                [innerHTML]=\"notifications['event_description']\"\n                                [ngStyle]=\"{\n                                  'color': notifications.viewed_datetime == '' ? '#000' : '#c4bbbb'\n                                }\">\n                              </span>\n                            </p>\n\n                            <span class=\"vertical-timeline-element-date\"></span>\n\n                          </div>\n                        </div>\n\n                      </div>\n\n                    </div>\n\n                  </perfect-scrollbar>\n                </div>\n\n              </div>\n\n              <ng-template #noNotifications>\n                <div>No New Notifications Found</div>\n              </ng-template>\n\n            </ng-template>\n          </li>\n\n        </ul>\n\n        <div [ngbNavOutlet]=\"notificationNav\"></div>\n\n      </div>\n\n      <div class=\"nav-justified\">\n        <ul class=\"nav flex-column\">\n          <li class=\"nav-item-divider nav-item mt-0\"></li>\n          <li class=\"nav-item-btn text-center nav-item\">\n            <a\n              [routerLink]=\"['/other/all-notificatons']\"\n              class=\"btn-pill btn btn-primary btn-sm text-white\">\n              {{\n                respData && respData.length > 0\n                  ? 'View More Notifications'\n                  : 'View Old Notifications'\n              }}\n            </a>\n          </li>\n        </ul>\n      </div>\n\n    </div>\n\n  </div>\n</div>";

