/***/ 89660:
/*!****************************************************************************************************!*\
  !*** ./projects/supervision/src/app/auth/components/dmc-login/dmc-login.component.html?ngResource ***!
  \****************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"login-banner-slider w-100\">\n    <div class=\"banner-bg \">\n        <div class=\"\">\n            <!-- <div class=\"banner-slider\">\n                <div class=\"banner-section\">\n                    <img src=\"assets/images/dmc_banner.png\">\n                </div>\n             </div> -->\n            <div class=\"container\">\n                <div class=\"row align-items-center\">\n                    <div class=\"col-6\">\n                        <div class=\"left-txt-sec\">\n                            <figure>\n                                <img src=\"assets/images/suppli-logo.svg\">\n                            </figure>\n                            <h1>Destination\n                                Management Company Login</h1>\n                        </div>\n                    </div>\n                    <div class=\"col-6\">\n                        <div class=\"login-form\">\n                            <div class=\"login-container\">\n                                <div class=\"alert alert-danger\" *ngIf=\"errorMessage\">\n                                    {{ errorMessage }}\n                                </div>\n                                <div class=\"login-content\">\n                                    <form autocomplete=\"off\" *ngIf=\"!showOtpComponent\"class=\"needs-validation\" [formGroup]=\"loginForm\"novalidate\n                                    (validSubmit)=\"onLogin()\">\n                                        \n                                        <div class=\"form-field\">\n                                            <label>Username</label>\n                                            <input placeholder=\"Username\" id=\"exampleEmail\" formControlName=\"email\" name=\"email\" type=\"email\"\n                                            class=\"form-control\">\n                                        </div>\n                                        <div class=\"form-field\">\n                                            <label>Password</label>\n                                            <input type=\"password\" placeholder=\"Password\"      formControlName=\"password\" id=\"examplePassword\" name=\"password\"\n                                            class=\"form-control\">\n                                        </div>\n                                        <div *ngIf=\" (loginForm.get('password').dirty || loginForm.get('password').touched) && loginForm.get('password').invalid\"\n                                        class=\"alert alert-danger\">\n                                        Password is required\n                                    </div>\n                                        <div class=\"login-footer\">\n                                            <div class=\"forgot-password\">\n                                                <a class=\"c-pointer\" routerLink=\"/auth/forgot-password\">Forgot Password ?</a>\n                                            </div>\n                                        </div>\n                                        <div>\n                                            <button type=\"submit\" class=\"btn srch_btn\">Login</button>\n                                        </div>\n                                        <div class=\"login-footer\">\n                                            <div class=\"register-here\">\n                                                <a class=\"c-pointer\" href=\"https://.com/b2b/#/auth/b2b\" target=\"_blank\" rel=\"noopener noreferrer\">\n                                                    New User? Register here\n                                                  </a>                                                  \n                                            </div>\n                                        </div>\n                                    </form>\n                                    <form [formGroup]=\"VerifyOtpForm\" (ngSubmit)=\"otpverify(VerifyOtpForm.value)\" *ngIf=\"showOtpComponent\">\n                                        <div class=\"row justify-content-center\">\n                                          <div class=\"col-12 col-md-6 col-lg-4\" style=\"min-width: 500px;\">\n                                            <div class=\"card bg-white mb-5 mt-5 border-0\" style=\"box-shadow: 0 12px 15px rgba(0, 0, 0, 0.02);\">\n                                              <div class=\"card-body p-5 text-center\">\n                                                <h4>Verify</h4>\n                                                <p>Your code was sent to you via email</p>\n                                                <div class=\"otp-field mb-4\">\n                                                  <ng-otp-input #ngOtpInput  (onInputChange)=\"onOtpChange($event)\" [config]=\"config\"></ng-otp-input>\n                                                </div>\n                                                <button type=\"submit\" class=\"btn btn-primary mb-3\">Verify</button>\n                                                <p class=\"resend text-muted mb-0\">\n                                                  Didn't receive code? <a (click)=\"requestAgain()\" style=\"cursor: pointer;\">Request again</a>\n                                                </p>\n                                                <div class=\"mb-3 login-footer\">\n                                                    <a class=\"btn w-100\" (click)=\"back()\">Back</a>\n                                                </div>\n                                           \n                                              </div>\n                                            </div>\n                                          </div>\n                                        </div>\n                                        </form> \n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n </div>\n\n\n\n\n";

/***/ }),

