module.exports = "<div class=\"h-100\">\n    <div class=\"row h-100 no-gutters\">\n        <!-- <div class=\"d-none d-lg-block col-lg-4\">\n            <div class=\"slider-light\">\n                <ngx-slick-carousel class=\"slick-slider slick-dotted\" #slickModal=\"slick-carousel\"\n                    [config]=\"slideConfig2\">\n                    <div ngxSlickItem>\n                        <div\n                            class=\"position-relative h-100 d-flex justify-content-center align-items-center bg-plum-plate\">\n                            <div class=\"slide-img-bg\"></div>\n                            <div class=\"slider-content text-light\">\n                                <h3>Perfect Balance</h3>\n                                <p>\n                                    ArchitectUI is like a dream. Some think it's too good to be true! Extensive\n                                    collection of\n                                    unified Vue Bootstrap Components and Elements.\n                                </p>\n                            </div>\n                        </div>\n                    </div>\n                    <div ngxSlickItem>\n                        <div\n                            class=\"position-relative h-100 d-flex justify-content-center align-items-center bg-premium-dark\">\n                            <div class=\"slide-img-bg\"></div>\n                            <div class=\"slider-content text-light\">\n                                <h3>Scalable, Modular, Consistent</h3>\n                                <p>\n                                    Easily exclude the components you don't require. Lightweight, consistent\n                                    Bootstrap based styles across all elements and components\n                                </p>\n                            </div>\n                        </div>\n                    </div>\n                    <div ngxSlickItem>\n                        <div\n                            class=\"position-relative h-100 d-flex justify-content-center align-items-center bg-sunny-morning\">\n                            <div class=\"slide-img-bg opacity-6\"></div>\n                            <div class=\"slider-content text-light\">\n                                <h3>Complex, but lightweight</h3>\n                                <p>\n                                    We've included a lot of components that cover almost all use cases for\n                                    any type of application.\n                                </p>\n                            </div>\n                        </div>\n                    </div>\n                </ngx-slick-carousel>\n            </div>\n        </div> -->\n        <div class=\"h-100 d-flex bg-white justify-content-center align-items-center col-md-12 col-lg-8\">\n            <div class=\"mx-auto app-login-box col-sm-12 col-md-8 col-lg-6\" >\n                <div class=\"app-logo\" height=\"50px\" width=\"204px\" style=\"background-size: cover !important; height: 50px !important;\"></div>\n                <h4>\n                    <div>Forgot your Password?</div>\n                    <span>Use the form below to recover it.</span>\n                </h4>\n                <div>\n                    <form autocomplete=\"off\" class=\"needs-validation\" [formGroup]=\"forgotPasswordForm\" novalidate\n                        (ngSubmit)=\"onSubmit()\">\n                        <div class=\"row\">\n                            <div class=\"col-md-9\">\n                                <fieldset class=\"form-group\">\n                                    <div tabindex=\"-1\" role=\"group\">\n                                        <label for=\"email\">Email</label>\n                                        <input formControlName=\"email\" type=\"text\" placeholder=\"Email here...\"\n                                            class=\"form-control\">\n                                    </div>\n                                </fieldset>\n                            </div>\n                        </div>\n                        <div class=\"row\">\n                        </div>\n                        <div class=\"mt-4 d-flex align-items-center\">\n                            <h6 class=\"mb-0\"><a routerLink=\"/auth/login\" class=\"text-primary\">Sign in existing\n                                    account</a></h6>\n                            <div class=\"ml-auto\">\n                                <button type=\"submit\" class=\"btn btn-primary btn-lg\" style=\"background-color: #3901be !important\">Recover Password</button>\n                            </div>\n                        </div>\n                    </form>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>";

