/***/ 12003:
/*!********************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/actvity-crs/components/activity/activity-crs-list/list-activity-crs.component.html?ngResource ***!
  \********************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card adminInner\">\n    <div class=\"card-header mb-3\">\n        <h5>{{'Experience List'}}</h5> \n        \n    </div>\n    <div class=\"d-flex align-items-center justify-content-between pb-3\">\n         <div></div>\n         <div class=\"form-group mb-0 col-sm-3 p-0 float-right has-search\">\n             Full text search:\n            <input class=\"form-control\" type=\"text\"  name=\"Search\" [(ngModel)]=\"searchText\" autocomplete=\"off\" placeholder=\"Search\">\n        </div>\n     </div>\n   \n\n<div class=\"wrapper1\" id=\"notifications-list\" (scroll)=\"scrollTwo.scrollLeft = scrollOne.scrollLeft\" #scrollOne >\n        <div class=\"div1\"></div>\n   </div>\n   <div class=\"wrapper2\" #scrollTwo (scroll)=\"scrollOne.scrollLeft = scrollTwo.scrollLeft\">\n        <div  class=\"div2 invisible-scrollbar\">\n    \n        <div class=\"table-responsive\">\n            <table class=\"table table-borderless table-striped table-hover\" matSort >\n                <thead>\n                    <tr>\n                        <th scope=\"col\" class=\"text-left text-nowrap\" *ngFor=\"let header of displayColumn;\"\n                            mat-sort-header=\"{{header.key}}\">\n                            {{header.value }} </th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr *ngIf=\"noData\">\n                        <td colspan=\"11\">\n                            <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\"></mat-spinner>\n                        </td>\n                    </tr>\n                    <tr *ngIf=\"!noData && !respData.length\">\n                        <td colspan=\"11\">\n                            <h4 class=\"text-muted text-center\">\n                                No Data Found!\n                            </h4>\n                        </td>\n                    </tr>\n                    <tr\n                        *ngFor=\"let data of respData | filter:searchText | slice: (page - 1) * pageSize : (page - 1) * pageSize + pageSize; let i=index;\">\n                        <td class=\"text-left text-muted\">{{i+1}}.</td>\n                        <td class=\"text-left\"> {{data?.activity_name}} </td>\n                        <td class=\"text-left\"> {{data?.supplier_name}} </td>\n                        <td class=\"text-left\"> {{data?.prime_user_name}} </td>\n                        <!-- <td class=\"text-left\"> {{data?.distribution_channel}} </td> -->\n                        <td class=\"text-left\"> \n                            <span *ngFor=\"let data of data?.activity_types_name; let last = last\">\n                                {{data}}<span *ngIf=\"!last\">, </span>\n                            </span>    \n                        </td>\n                        <td class=\"text-left\"> {{data?.activity_country_name}} </td>\n                        <td class=\"text-left\"> {{data?.activity_city_name}} </td>\n                        <td class=\"text-left\"> {{data?.activity_duration}} {{data?.activity_duration_type}} </td>\n                        <td class=\"text-left\"> {{data?.currency}} </td>\n                        <td class=\"text-left\"> {{getValidTillDate(data?.seasons)}} </td>\n                         <td class=\"text-left\" >\n                            <label class=\"checkbox-label\">\n                                <input type=\"checkbox\" class=\"checkbox-input\" [checked]=\"data.publish_status === 1\" (change)=\"enablePublish($event.target.checked,data)\">\n                                <span class=\"checkbox-text ml-2\">Enable</span>\n                            </label> \n                        </td>\n                         <!-- <td class=\"text-left\" *ngIf=\"loggedInUser.auth_role_id !== 7\" >\n                            <label class=\"checkbox-label\">\n                                <input type=\"checkbox\" class=\"checkbox-input\" [checked]=\"data.book_now_status === 1\" (change)=\"enableBookNow($event.target.checked,data)\">\n                                <span class=\"checkbox-text ml-2\">Enable</span>\n                            </label> \n                        </td> -->\n                        <td class=\"text-left\">\n                            <div ngbDropdown container=\"body\"><button\n                                    class=\"btnStyle\" ngbDropdownToggle>\n                                    {{'Action'}}\n                                </button>\n                                <div ngbDropdownMenu>\n                                    <!-- <button ngbDropdownItem\n                                        (click)=\"updateseasonPrice(data.activity_id,'add', data)\">Add Price</button> -->\n                                    <!-- <button ngbDropdownItem\n                                        (click)=\"updateseasonPrice(data.activity_id,'update', data)\">Update Price</button> -->\n                                    <button ngbDropdownItem\n                                        (click)=\"updateActivity(data)\">Update Activity</button>\n                                    <button ngbDropdownItem\n                                        (click)=\"cancelDeletePopup(data.activity_id)\">Delete</button>\n                                </div>\n                            </div>\n                        </td>\n\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n        </div>\n        </div>\n        <div class=\"card-footer pb-0\">\n            <div class=\"d-flex w-100 justify-content-between\">\n                <ngb-pagination [collectionSize]=\"collectionSize\" [maxSize]=\"12\" [rotate]=\"true\" [boundaryLinks]=\"true\" [(page)]=\"page\"\n                    [pageSize]=\"pageSize\">\n                </ngb-pagination>\n                <select class=\"custom-select\" style=\"width: auto\" name=\"pageSize\" [(ngModel)]=\"pageSize\">\n                    <option [ngValue]=\"10\">10 items per page</option>\n                    <option [ngValue]=\"20\">20 items per page</option>\n                    <option [ngValue]=\"50\">50 items per page</option>\n                </select>\n            </div>\n        </div>\n    \n</div>\n\n  <ngx-loading [show]=\"loading\"\n  [config]=\"{primaryColour: primaryColour, secondaryColour: secondaryColour, tertiaryColour: primaryColour, backdropBorderRadius: '3px',fullScreenBackdrop:true}\"\n  [template]=\"loadingTemplate\"></ngx-loading>";

/***/ }),

