/***/ 23830:
/*!*************************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/b2c-cms/components/add-or-modify-meditation-retreat/add-or-modify-meditation-retreat.component.html?ngResource ***!
  \*************************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "\n\n<div class=\"card adminInner\">\n  <div class=\"card-header mb-3\">\n  <h5>Meditation Retreat</h5>\n</div>\n  <form [formGroup]=\"regConfig\" autocomplete=\"off\">\n\n    <div class=\"form-row\">\n\n      <!-- Retreat Name -->\n      <div class=\"col-6 pr-0\">\n        <div class=\"form-group\">\n          <label>Retreat Name*</label>\n          <input\n            type=\"text\"\n            class=\"form-control form-control-sm\"\n            placeholder=\"Retreat Name\"\n            formControlName=\"retreat_name\">\n        </div>\n      </div>\n\n      <!-- Duration -->\n      <div class=\"col-6 pr-0\">\n        <div class=\"form-group\">\n          <label>Duration*</label>\n          <input\n            type=\"text\"\n            class=\"form-control form-control-sm\"\n            placeholder=\"e.g. 7 Days\"\n            formControlName=\"duration\">\n        </div>\n      </div>\n\n      <!-- Description -->\n      <div class=\"col-12 pr-0\">\n        <div class=\"form-group\">\n          <label>Description*</label>\n          <textarea\n            rows=\"2\"\n            class=\"form-control form-control-sm\"\n            placeholder=\"Description\"\n            formControlName=\"description\">\n          </textarea>\n        </div>\n      </div>\n\n      <!-- Image -->\n      <div class=\"col-6 pr-0\">\n        <div class=\"form-group\">\n          <label>Image*</label>\n          <input\n            type=\"file\"\n            class=\"form-control form-control-sm\"\n            accept=\".png,.jpg,.jpeg\"\n            (change)=\"onFileChange($event.target.files)\"\n             #fileInput>\n\n          <div *ngIf=\"imageSrc\" class=\"mt-2\">\n            <img [src]=\"imageSrc\" width=\"120\" height=\"60\" class=\"rounded\">\n          </div>\n\n          <small class=\"text-danger\">\n            Max file size: 1 MB\n          </small>\n        </div>\n      </div>\n\n    </div>\n\n    <!-- Buttons -->\n    <div class=\"mt-3\">\n      <button type=\"button\" class=\"btn btn-primary btn-sm\" (click)=\"onSearchSubmit()\">\n        {{ btnName }}\n      </button>\n      &nbsp;\n      <button type=\"button\" class=\"btn btn-secondary btn-sm\" (click)=\"onReset()\">\n        Reset\n      </button>\n    </div>\n\n  </form>\n</div>\n\n<!-- LIST -->\n<div class=\"card adminInner mt-3\">\n  <div class=\"card-body p-0\">\n\n    <p>Total {{ respData?.length }} Retreats</p>\n\n    <table class=\"table table-borderless table-striped table-hover\">\n      <thead>\n        <tr>\n          <th>#</th>\n          <th>Retreat Name</th>\n          <th>Duration</th>\n          <th>Description</th>\n          <th>Image</th>\n          <th>Actions</th>\n        </tr>\n      </thead>\n\n      <tbody>\n        <tr *ngIf=\"!respData.length\">\n          <td colspan=\"6\" class=\"text-center text-muted\">No Data Found</td>\n        </tr>\n\n        <tr *ngFor=\"let item of respData; let i=index\">\n          <td>{{ i + 1 }}</td>\n          <td>{{ item.retreat_name }}</td>\n          <td>{{ item.duration }}</td>\n          <td>{{ item.description }}</td>\n          <td>\n            <img *ngIf=\"item.image_url\"\n              [src]=\"getImage(item.image_url)\"\n              width=\"80\"\n              height=\"40\">\n          </td>\n          <td>\n            <button (click)=\"editList(item)\" class=\"btnStyle mr-2\">\n              Edit\n            </button>\n            <button (click)=\"deleteList(item.id)\" class=\"btnStyle\">\n              Delete\n            </button>\n          </td>\n        </tr>\n      </tbody>\n\n    </table>\n\n  </div>\n</div>\n";

/***/ }),

