"use strict";
module.exports = "<div class=\"\">\n\n  <div class=\"\">\n\n    <ul\n      ngbNav\n      #tabs=\"ngbNav\"\n      class=\"tabs-animated custom_tab\"\n      [(activeId)]=\"activeIdString\"\n      (navChange)=\"beforeChange($event)\">\n\n      <li [ngbNavItem]=\"'add_update_staticPage'\">\n\n        <a ngbNavLink>\n          Service FAQ Page Content\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-add-update-service-faq\n            (staticContentTab)=\"triggerTab($event)\">\n          </app-add-update-service-faq>\n        </ng-template>\n\n      </li>\n\n      <li [ngbNavItem]=\"'staticpage_list'\">\n\n        <a ngbNavLink>\n          Service FAQ Page List\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-list-service\n            (staticContentTab)=\"triggerTab($event)\">\n          </app-list-service>\n        </ng-template>\n\n      </li>\n\n    </ul>\n\n    <div [ngbNavOutlet]=\"tabs\"></div>\n\n  </div>\n\n</div>";

