/***/ 3177:
/*!***********************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/b2c-cms/components/general-modal-image/general-modal-image.component.html?ngResource ***!
  \***********************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card adminInner\">\n  <div class=\"card-header mb-3\">\n    <h5>Auth Screen Image</h5>\n  </div>\n\n  <form [formGroup]=\"regConfig\" autocomplete=\"off\">\n\n    <div class=\"form-row\">\n\n      <!-- Dropdown -->\n      <div class=\"col-6 pr-0\">\n        <div class=\"form-group\">\n          <label>Type*</label>\n          <select class=\"form-control form-control-sm\"\n                  formControlName=\"type\">\n            <option value=\"\">Select Type</option>\n            <option value=\"login\">Login</option>\n            <option value=\"register\">Register</option>\n            <option value=\"forgot_password\">Forgot Password</option>\n          </select>\n        </div>\n      </div>\n\n      <!-- Image Upload -->\n      <div class=\"col-6 pr-0\">\n        <div class=\"form-group\">\n          <label>Image*</label>\n\n          <input\n            type=\"file\"\n            class=\"form-control form-control-sm\"\n            accept=\".png,.jpg,.jpeg\"\n            (change)=\"onFileChange($event.target.files)\"\n            #fileInput>\n\n          <!-- File Name -->\n          <div *ngIf=\"selectedFileName\" class=\"mt-1 text-muted\">\n            Selected File: {{ selectedFileName }}\n          </div>\n\n          <!-- Preview -->\n          <div *ngIf=\"imageSrc\" class=\"mt-1\">\n            <img [src]=\"imageSrc\" width=\"120\" height=\"70\" class=\"rounded\">\n          </div>\n\n          <small class=\"text-danger\">\n            (JPG, PNG only | Max 1MB)\n          </small>\n        </div>\n      </div>\n\n    </div>\n\n    <!-- Buttons -->\n    <div class=\"btncontainer\">\n      <button type=\"button\"\n              class=\"btn btn-primary\"\n              (click)=\"onSubmit()\">\n        {{ btnName }}\n      </button>\n\n      <button type=\"button\"\n              class=\"btn btn-secondary ml-2\"\n              (click)=\"onReset()\">\n        Reset\n      </button>\n    </div>\n\n  </form>\n</div>";

/***/ }),

