"use strict";
module.exports = "<div class=\"\">\n\n  <div class=\"\">\n\n    <ul\n      ngbNav\n      #tabs=\"ngbNav\"\n      class=\"tabs-animated custom_tab\"\n      [(activeId)]=\"activeIdString\"\n      (navChange)=\"beforeChange($event)\">\n\n      <li [ngbNavItem]=\"'newsletter'\">\n\n        <a ngbNavLink>\n          NewsLetter Subscriptions\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-newsletter-subscription\n            (updateSubscription)=\"triggerTab($event)\">\n          </app-newsletter-subscription>\n        </ng-template>\n\n      </li>\n\n      <!-- Optional tab kept commented as-is -->\n      <!--\n      <li [ngbNavItem]=\"'deals'\">\n\n        <a ngbNavLink>\n          <i class=\"fa fa-list\"></i> &nbsp; Deals/Offers Subscription\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-deals-subscription\n            (updateSubscription)=\"triggerTab($event)\">\n          </app-deals-subscription>\n        </ng-template>\n\n      </li>\n      -->\n\n    </ul>\n\n    <div [ngbNavOutlet]=\"tabs\"></div>\n\n  </div>\n\n</div>";

