/***/ 70228:
/*!************************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/cms/components/static-page-content/components/add-update-content/add-update-content.component.html?ngResource ***!
  \************************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card adminInner\" style=\"padding: 20px;\">\n    <!-- <div class=\"add-traveller\"> -->\n        <div class=\"card-header mb-3\">\n            <h5>Static Page Content</h5>\n        </div>\n        <div class=\"custom-inline-form\">\n            <form class=\"\" [formGroup]=\"regConfig\" autocomplete=\"off\">\n                <div class=\"form-group required row\">\n                    <label for=\"title\" class=\"col-sm-2 col-form-label\">Page Title</label>\n                    <div class=\"col-sm-4\">\n                        <select id=\"inputState\" class=\"form-control\" formControlName=\"title\">\n                            <option value=\"\" disabled>Choose..</option>\n                            <option *ngFor=\"let t of TitleList\" value=\"{{t.name}}\">{{t.name}}</option>\n                        </select>\n                    </div>\n                </div>\n                <div class=\"form-group required row\">\n                    <label for=\"firstName\" class=\"required\" class=\"col-sm-2 col-form-label\">Page Title</label>\n                    <div class=\"col-sm-4\">\n                        <input type=\"text\" class=\"form-control text-capitalize\" id=\"firstName\" maxlength=\"50\"\n                           formControlName=\"page_title\">\n\n                    </div>\n                </div>\n                <div class=\"form-group required row\">\n                    <label for=\"description\" class=\"col-sm-2 col-form-label\">Page Description</label>\n                    <div class=\"col-sm-10\">\n                        <ckeditor [(ngModel)]=\"model.editorData\" formControlName=\"page_description\"\n                            [(config)]=\"editorConfig\"></ckeditor>\n                    </div>\n                </div>\n                <div class=\"form-group required row\">\n                    <label for=\"lastName\" class=\"col-sm-2 col-form-label\">Page SEO Title</label>\n                    <div class=\"col-sm-4\">\n                        <input type=\"text\" class=\"form-control text-capitalize\" id=\"lastName\" maxlength=\"20\"\n                            (keypress)=\"omitSpecialCharacters($event)\" formControlName=\"page_seo_title\">\n                    </div>\n                </div>\n                <div class=\"form-group required row\">\n                    <label for=\"lastName\" class=\"col-sm-2 col-form-label\">Page SEO Keyword</label>\n                    <div class=\"col-sm-4\">\n                        <input type=\"text\" class=\"form-control text-capitalize\" id=\"lastName\" maxlength=\"20\"\n                            (keypress)=\"omitSpecialCharacters($event)\" formControlName=\"page_seo_keyword\">\n                    </div>\n                </div>\n                <div class=\"form-group required row\">\n                    <label for=\"lastName\" class=\"col-sm-2 col-form-label\">Page SEO Description</label>\n                    <div class=\"col-sm-4\">\n                        <input type=\"text\" class=\"form-control text-capitalize\" id=\"lastName\" maxlength=\"100\"\n                            (keypress)=\"omitSpecialCharacters($event)\" formControlName=\"page_seo_description\">\n                    </div>\n                </div>\n                <div class=\"form-group required row\">\n                    <label for=\"lastName\" class=\"col-sm-2 col-form-label\">Page Redirection Url</label>\n                    <div class=\"col-sm-4\">\n                        <input type=\"text\" class=\"form-control\" id=\"lastName\" maxlength=\"150\"\n                             formControlName=\"page_redirection_url\">\n                    </div>\n                </div>\n                <div class=\"form-group required row\">\n                    <label for=\"country\" class=\"col-sm-2 col-form-label\">Page Position</label>\n                    <div class=\"col-sm-4\">\n                        <select id=\"country\" class=\"form-control\" formControlName=\"page_position\">\n                            <option selected value=\"\" disabled>Choose..</option>\n                            <option *ngFor=\"let p of Positions\" value=\"{{p.name}}\">{{p.name}}</option>\n                        </select>\n                    </div>\n                </div>\n                <div class=\"form-group row mb-n2\">\n                    <div class=\"col-sm-12 customCenter\">\n                        <button type=\"submit\" class=\"btn btn-sm btn-primary mr-1\" (click)=\"onSubmit()\">Submit</button>\n                        <button type=\"reset\" class=\"btn btn-sm btn-primary\" (click)=\"onReset()\">Reset</button>\n                    </div>\n                </div>\n            </form>\n        </div>\n    <!-- </div> -->\n</div>";

/***/ }),

