"use strict";
module.exports = "<div class=\"card mt-3\">\n    <div class=\"card-body\">\n        <div class=\"mb-3\">\n            <form>\n                <div class=\"table-responsive\">\n                    <table class=\"table table-borderless table-striped table-hover\" matSort\n                        (matSortChange)=\"sortData($event)\">\n                        <thead>\n                            <tr>\n                                <th scope=\"col\" class=\"text-left text-nowrap\" *ngFor=\"let header of displayColumn;\"\n                                    mat-sort-header=\"{{header.key}}\">\n                                    {{header.value }}\n                                </th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr *ngIf=\"noData\">\n                                <td colspan=\"11\">\n                                    <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\"></mat-spinner>\n                                </td>\n                            </tr>\n                            <tr *ngIf=\"!noData && !respData.length\">\n                                <td colspan=\"11\">\n                                    <h4 class=\"text-muted text-center\">\n                                        No Data Found!\n                                    </h4>\n                                </td>\n                            </tr>\n                            <tr\n                                *ngFor=\"let data of respData | slice: (page - 1) * pageSize : (page - 1) * pageSize + pageSize; let i=index;\">\n                                <td class=\"text-left text-muted\">{{i+1}}.</td>\n                                <td class=\"text-left\"> \n                                    <button class=\"btn btn-sm btn-primary\"\n                                        (click)=\"viewCommission(data)\">\n                                        <i class=\"far fa-list-alt text-nowrap\">\n                                            {{'View'}}\n                                        </i>\n                                    </button>\n                                </td>\n                                <td class=\"text-left text-uppercase\">\n                                    {{data['business_name'] ?\n                                    data['business_name'] : 'N/A'}}\n                                </td>\n                                <td class=\"text-left\">\n                                    {{data['uuid'] ? data['uuid'] : 'N/A'}}\n                                </td>\n                                <td class=\"text-left capitalize\">\n                                    {{data['first_name'] +' '+\n                                    data['last_name']}} </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                <div class=\"card-footer pb-0\">\n                    <div class=\"d-flex w-100 justify-content-between\">\n                        <ngb-pagination [collectionSize]=\"collectionSize\" [maxSize]=\"12\" [rotate]=\"true\" [boundaryLinks]=\"true\" [(page)]=\"page\" [pageSize]=\"pageSize\">\n                        </ngb-pagination>\n                        <select class=\"custom-select\" style=\"width: auto\" name=\"pageSize\" [(ngModel)]=\"pageSize\">\n                            <option [ngValue]=\"50\">50 items per page</option>\n                            <option [ngValue]=\"100\">100 items per page</option>\n                            <option [ngValue]=\"150\">150 items per page</option>\n                            <option [ngValue]=\"200\">200 items per page</option>\n                            <option [ngValue]=\"250\">250 items per page</option>\n                            <option [ngValue]=\"500\">500 items per page</option>\n                            <option [ngValue]=\"1000\">1000 items per page</option>\n                        </select>\n                    </div>\n                </div>\n            </form>\n        </div>\n    </div>\n</div>";

