/***/ 20209:
/*!***************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/dashboard/components/latest-members/latest-members.component.html?ngResource ***!
  \***************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card mb-3\">\n    <div class=\"card-header-tab card-header\">\n        <div class=\"card-header-title font-size-lg text-capitalize font-weight-normal\">\n            <i class=\"header-icon lnr-laptop-phone mr-3 text-muted opacity-6\"> </i>\n            {{'Latest Members'}}\n        </div>\n        <div class=\"\">\n            <sup>\n                <span *ngIf=\"howManyAgentUser\"> <small class=\"badge badge-info m-1\"> {{howManyAgentUser}} B2B Users\n                    </small> </span>\n                <span *ngIf=\"howManySubAgentUser\"> <small class=\"badge badge-info m-1\"> {{howManySubAgentUser}}\n                        Sub-Agent Users </small></span>\n                <span *ngIf=\"howManyStaffUser\"> <small class=\"badge badge-info m-1\"> {{howManyStaffUser}} Staff Users\n                    </small> </span>\n            </sup>\n        </div>\n    </div>\n    <div class=\"card-body\">\n        <ul class=\"w-100 p-0 border rounded\">\n            <li class=\"w-100\" *ngIf=\"noDataFound; else notShow;\">\n                <!-- <mat-spinner [diameter]=\"30\" mode=\"indeterminate\" style=\"margin: 0 auto;\"></mat-spinner> -->\n                <div class=\"text-center\">\n                    No data found\n                </div>\n            </li>\n            <ng-template #notShow>\n                <li class=\"w-25 text-center\" *ngFor=\"let item of latestMembers | slice: 0:8; let i = index;\">\n                    <img class=\"rounded-circle p-4 w-100\" src=\"./assets/images/avatars/face.png\" alt=\"\">\n                    <div class=\"w-100\">\n                        <i class=\"fa fa-circle\"></i>\n                        <span class=\"text-dark f-16 text-truncate\"> {{ item['first_name'] }} </span>\n                    </div>\n                    <div class=\"w-100 text-muted f-12\">\n                        {{'(Since:'}} {{item['created_at'] | date: 'MMM, y'}} {{')'}}\n                    </div>\n                </li>\n                <!-- <li class=\"text-center p-2 mt-3 w-100 btop\">\n                    <a [routerLink]=\"['/user/subAdmin/active']\" [queryParams]=\"{type: 'active'}\">\n                        View More\n                    </a>\n                </li> -->\n            </ng-template>\n        </ul>\n    </div>\n</div>";

/***/ }),

/***/ 58307:
/*!*****************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/dashboard/components/recent-booking-transactions/recent-booking-transactions.component.html?ngResource ***!
  \*****************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card mb-3\">\n    <div class=\"card-header-tab card-header\">\n        <div class=\"card-header-title font-size-lg text-capitalize font-weight-normal\">\n            <i class=\"header-icon lnr-laptop-phone mr-3 text-muted opacity-6\"> </i>\n            {{'Recent Booking Transactions'}}\n        </div>\n    </div>\n    <div class=\"card-body\">\n        <ul class=\"list-group\">\n            <li class=\"list-group-item\" *ngIf=\"noDataFound; else notShow;\">\n                <!-- <mat-spinner [diameter]=\"30\" mode=\"indeterminate\" style=\"margin: 0 auto;\"></mat-spinner> -->\n                <div class=\"text-center\">\n                    No data found\n                </div>\n            </li>\n            <ng-template #notShow>\n                <li class=\"list-group-item\" *ngFor=\"let item of recentBookingTransactions | slice: 0:8\">\n                    <div class=\"row\">\n                        <div class=\"col-sm-1\">\n                            <i class=\"fa fa-exchange\"></i>\n                        </div>\n                        <div class=\"col-sm-9\">\n                            <span class=\"f-12 w-50\">\n                                <div class=\"\">\n                                    <a >\n                                        {{item['system_transaction_id']}}-{{item['date_of_transaction'] | date: 'medium'}}\n                                    </a>\n                                </div>\n                                <div [ngStyle]=\"{'color' : item['transaction_type'] == 'Cash' ? 'orange' : item['transaction_type'] == 'CreditLimit' ? 'purple' : item['transaction_type'] == 'Flight' ? 'blue' : item['transaction_type'] == 'Car' ? 'yellow' : item['transaction_type'] == 'hotel' ? 'green' : '' }\" [innerHTML]=\"item['remarks']\"></div>\n                            </span>\n                        </div>\n                        <div class=\"col-sm-2\">\n                            <span class=\"badge badge-primary\">\n                                {{item['amount']}}\n                            </span>\n                        </div>\n                    </div>\n                </li>\n                <li class=\"text-center p-2\" id=\"list-style\">\n                    <a [routerLink]=\"['/transaction-logs']\">\n                        View More\n                    </a>\n                </li>\n            </ng-template>\n        </ul>\n    </div>\n</div>";

/***/ }),

