module.exports = "<div class=\"col-12 revenue-finance-top-sec mt-3 pt-2 pb-4\">\n\n    <!-- Header -->\n    <div class=\"row\">\n        <div class=\"col-12\">\n            <span class=\"revenue-span\">Geo / Route</span>\n        </div>\n    </div>\n\n<div class=\"row p-3\">\n  <div class=\"col-12 mb-2\" *ngFor=\"let item of geoRoutes\">\n    <div class=\"head-sect\">\n      <div class=\"row p-2 align-items-center\">\n        <div class=\"col-8\">\n          <span class=\"f-17\">{{ item }}</span>\n        </div>\n\n        <div class=\"col-4 text-end\">\n          <span class=\"f-17\">></span>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n</div>";

