"use strict";
module.exports = "<ul ngbNav #tabs=\"ngbNav\" class=\"tabs-animated custom_tab crs-tab-ui\" [(activeId)]=\"activeIdString\" (navChange)=\"onTabSelected($event)\">\n\n\n  <li [ngbNavItem]=\"'list_operators'\">\n\n    <a ngbNavLink>\n      <span>Operators List</span>\n    </a>\n\n    <ng-template ngbNavContent>\n      <app-operators-list></app-operators-list>\n      </ng-template>\n\n  </li>\n\n\n  <li [ngbNavItem]=\"'add_operators'\">\n\n    <a ngbNavLink>\n      <span>Add/ Edit Operators</span>\n    </a>\n\n    <ng-template ngbNavContent>\n     <app-add-update-operators-list></app-add-update-operators-list>\n    </ng-template>\n    \n  </li> \n\n</ul>\n\n<div [ngbNavOutlet]=\"tabs\"></div>\n\n";

