/***/ 30667:
/*!***************************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/heli-crs/components/heli-pricing-rules/add-update-pricing-list/add-update-pricing-list.component.html?ngResource ***!
  \***************************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card adminInner mt-3\">\n\n    <div class=\"card-header mb-4\">\n        <h5>{{ isEdit ? 'Update Pricing Rules' : 'Add Pricing Rules' }}</h5>\n    </div>\n\n    <form [formGroup]=\"pricingForm\" (ngSubmit)=\"onSubmit()\">\n\n        <div class=\"row\">\n\n            <!-- ================= OPERATOR ================= -->\n            <div class=\"col-md-4 mb-3 pr-0\">\n\n                <label>Operator Name</label>\n\n                <select class=\"form-control\" formControlName=\"operator_name\">\n\n                    <option value=\"\">Select Operator</option>\n\n                    <option *ngFor=\"let op of operatorsList\" [value]=\"op.operator_name\">\n                        {{ op.operator_name }}\n                    </option>\n\n                </select>\n\n                <small class=\"text-danger\" *ngIf=\"submitted && pricingForm.get('operator_name')?.errors?.required\">\n                    Operator is required\n                </small>\n\n            </div>\n\n            <!-- ================= ROUTE ================= -->\n            <div class=\"col-md-4 mb-3\">\n\n                <label>Route</label>\n\n                <select class=\"form-control\" formControlName=\"route_id\">\n\n                    <option value=\"\">Select Route</option>\n\n                    <option *ngFor=\"let rt of routesList\" [value]=\"rt.id\">\n                        {{ rt.route_name || rt.route }}\n                    </option>\n\n                </select>\n\n                <small class=\"text-danger\" *ngIf=\"submitted && pricingForm.get('route_id')?.errors?.required\">\n                    Route is required\n                </small>\n\n            </div>\n\n            <!-- ================= BASE FARE ================= -->\n            <div class=\"col-md-4 mb-3 pl-0\">\n\n                <label>Base Fare</label>\n\n                <input type=\"text\" class=\"form-control\" formControlName=\"base_fare\">\n\n                <small class=\"text-danger\" *ngIf=\"submitted && pricingForm.get('base_fare')?.errors?.required\">\n                    Base fare is required\n                </small>\n\n                <small class=\"text-danger\" *ngIf=\"submitted && pricingForm.get('base_fare')?.errors?.pattern\">\n                    Only numbers allowed\n                </small>\n\n            </div>\n\n            <!-- ================= TAXES ================= -->\n            <div class=\"col-md-4 mb-3 pr-0\">\n\n                <label>Taxes</label>\n\n                <input type=\"text\" class=\"form-control\" formControlName=\"taxes\">\n\n                <small class=\"text-danger\" *ngIf=\"submitted && pricingForm.get('taxes')?.errors?.required\">\n                    Taxes is required\n                </small>\n\n                <small class=\"text-danger\" *ngIf=\"submitted && pricingForm.get('taxes')?.errors?.pattern\">\n                    Only numbers allowed\n                </small>\n\n            </div>\n\n            <!-- ================= EFFECTIVE FROM ================= -->\n            <div class=\"col-md-4 mb-3\">\n\n                <label>Effective From</label>\n\n                <input type=\"date\" class=\"form-control\" formControlName=\"effective_from\">\n\n                <small class=\"text-danger\" *ngIf=\"submitted && pricingForm.get('effective_from')?.errors?.required\">\n                    Effective From is required\n                </small>\n\n            </div>\n\n            <!-- ================= EFFECTIVE TO ================= -->\n            <div class=\"col-md-4 mb-3 pl-0\">\n\n                <label>Effective To</label>\n\n                <input type=\"date\" class=\"form-control\" formControlName=\"effective_to\">\n\n                <small class=\"text-danger\" *ngIf=\"submitted && pricingForm.get('effective_to')?.errors?.required\">\n                    Effective To is required\n                </small>\n\n            </div>\n\n            <!-- ================= STATUS ================= -->\n            <div class=\"col-md-4 mb-3\">\n\n                <label class=\"d-block\">Status</label>\n\n                <label class=\"switch\">\n                    <input type=\"checkbox\" formControlName=\"status\">\n                    <span class=\"slider round\"></span>\n                </label>\n\n            </div>\n\n        </div>\n\n        <!-- ================= BUTTONS ================= -->\n        <div class=\"text-left btncontainer\">\n\n            <button type=\"submit\" class=\"btn btn-primary mr-2\">\n                {{ isEdit ? 'Update' : 'Save' }}\n            </button>\n\n            <button type=\"button\" class=\"btn btn-secondary\" (click)=\"resetForm()\">\n                Reset\n            </button>\n\n        </div>\n\n    </form>\n\n</div>";

/***/ }),

