"use strict";
module.exports = "<ul ngbNav #tabs=\"ngbNav\" class=\"tabs-animated custom_tab crs-tab-ui\" [(activeId)]=\"activeIdString\" (navChange)=\"onTabSelected($event)\">\n\n\n  <li [ngbNavItem]=\"'list_pricing_rules'\">\n\n    <a ngbNavLink>\n      <span>Pricing Rules List</span>\n    </a>\n\n    <ng-template ngbNavContent>\n      <app-pricing-list></app-pricing-list>\n    </ng-template>\n\n  </li>\n\n\n  <li [ngbNavItem]=\"'add_pricing_rules'\">\n\n    <a ngbNavLink>\n      <span>Add/ Edit Pricing Rules</span>\n    </a>\n\n    <ng-template ngbNavContent>\n      <app-add-update-pricing-list></app-add-update-pricing-list>\n    </ng-template>\n\n  </li>\n\n</ul>\n\n<div [ngbNavOutlet]=\"tabs\"></div>";

