"use strict";
module.exports = "<div class=\"card adminInner\">\n\n    <div class=\"card-header mb-3\">\n        <h5>Terms And Conditions</h5>\n    </div>\n\n\n    <div class=\"mb-3\">\n        <form [formGroup]=\"termsandConditionForm\" (ngSubmit)=\"onSubmitTermsAndConditions()\">\n            <div class=\"form-row\">\n                <div class=\"col-12 pr-0\">\n                    <div class=\"form-group  p-0\">\n                        <label for=\"activity_language_name\">Terms And Conditions</label>\n                        <ckeditor type=\"text\" formControlName=\"terms_and_conditions\" style=\"height: auto;\"></ckeditor>\n                    </div>\n                </div>\n\n            </div>\n            <div class=\"saveButton\">\n                <button type=\"submit\" class=\" btn-primary mr-2\"> {{saveTextName}}</button>\n                <button type=\"button\" class=\"btn btn-secondary\" (click)=\"clearForm()\">Cancel</button>\n            </div>\n        </form>\n    </div>\n</div>\n\n<ngx-loading [show]=\"loading\"\n    [config]=\"{primaryColour: primaryColour, secondaryColour: secondaryColour, tertiaryColour: primaryColour, backdropBorderRadius: '3px',fullScreenBackdrop:true}\"\n    [template]=\"loadingTemplate\"></ngx-loading>";

