"use strict";
module.exports = "<ul ngbNav #tabs=\"ngbNav\" class=\"tabs-animated custom_tab crs-tab-ui\" [(activeId)]=\"activeIdString\" (navChange)=\"onTabSelected($event)\">\n\n\n  <li [ngbNavItem]=\"'list_helipads'\">\n\n    <a ngbNavLink>\n      <span>Helipads List</span>\n    </a>\n\n    <ng-template ngbNavContent>\n      <app-helipads-list></app-helipads-list>\n      </ng-template>\n\n  </li>\n\n\n  <li [ngbNavItem]=\"'add_helipads'\">\n\n    <a ngbNavLink>\n      <span>Add/ Edit Helipads</span>\n    </a>\n\n    <ng-template ngbNavContent>\n     <app-add-update-helipads-list></app-add-update-helipads-list>\n    </ng-template>\n    \n  </li> \n\n</ul>\n\n<div [ngbNavOutlet]=\"tabs\"></div>\n\n";

