/***/ 57272:
/*!********************************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/hotel-crs/components/children-pollicy/component/children-pollicy-list/children-pollicy-list.component.html?ngResource ***!
  \********************************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"mb-3 btop\">\n    <div class=\"card-header-tab card-header\">\n        <div class=\"card-header-title font-size-lg text-capitalize font-weight-normal\">\n            <i class=\"header-icon lnr-laptop-phone mr-3 text-muted opacity-6\"> </i> {{'Children policy List'}}\n        </div>\n    </div>\n    <form>\n        <!-- <div class=\"p-2\">\n            <div class=\"form-group form-inline mb-0\">\n                Full text search:\n                <input class=\"form-control ml-2\" type=\"text\" name=\"searchTerm\"\n                    (keyup)=\"applyFilter($event.target.value)\" />\n            </div>\n        </div> -->\n        <div class=\"table-responsive\">\n            <table class=\"table table-borderless table-striped table-hover\" matSort (matSortChange)=\"sortData($event)\">\n                <thead>\n                    <tr>\n                        <th scope=\"col\" class=\"text-left text-nowrap\" *ngFor=\"let header of displayColumn;\"\n                            mat-sort-header=\"{{header.key}}\">\n                            {{header.value }} \n                        </th>\n                \n                        <th scope=\"col\" class=\"text-left text-nowrap\" *ngFor=\"let meal of mealHeaders\">\n                            {{ meal | titlecase }}\n                        </th>\n                        <th scope=\"col\" class=\"text-left text-nowrap\" *ngFor=\"let header of displayColumns;\"\n                        mat-sort-header=\"{{header.key}}\">\n                        {{header.value }} \n                    </th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr *ngIf=\"noData\">\n                        <td colspan=\"11\">\n                            <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\"></mat-spinner>\n                        </td>\n                    </tr>\n                    <tr *ngIf=\"!noData && !respData.length\">\n                        <td colspan=\"11\">\n                            <h4 class=\"text-muted text-center\">\n                                No Data Found!\n                            </h4>  \n                        </td>\n                    </tr>\n                    <tr\n                        *ngFor=\"let data of respData | slice: (page - 1) * pageSize : (page - 1) * pageSize + pageSize; let i=index;\">\n                        <td class=\"text-left text-muted\">{{i+1}}.</td>\n                        <td class=\"text-left\"> {{data['is_accommodation'] == 1 ? 'Yes' : 'No'}} </td>\n                        <td class=\"text-left\"> {{data['is_meals'] == 1 ? 'Yes' : 'No'}} </td>\n                        <td class=\"text-left\"> {{data['children_free_accom']}} </td>\n                        <td class=\"text-left\"> {{data['accom_children_from_age']}} </td>\n                        <td class=\"text-left\"> {{data['accom_children_to_age']}} </td>\n                        <!-- <td class=\"text-left\"> {{data['accommodation_charge']}} </td> -->\n                        <td class=\"text-left\"> {{data['children_free_meals']}} </td>\n                        <td class=\"text-left\"> {{data['meal_children_from_age']}} </td>\n                        <td class=\"text-left\"> {{data['meal_children_to_age']}} </td>\n                        <td *ngFor=\"let key of mealHeaders\" class=\"text-left\">\n                            {{ data[key] || 0}}\n                        </td>\n                        <td class=\"text-left\"> {{data['discount_value']}} (%)</td>\n                   \n                        <td>\n                            <span title=\"Slide for Active/Deactive\">\n                                {{status}}\n                                <mat-slide-toggle readonly class=\"example-margin\" [color]=\"''\"\n                                    [checked]=\"data['status']\" [(ngModel)]=\"data['status']\" name=\"status{{i}}\"\n                                    (click)=\"onStatusUpdate(data, i)\">\n                                </mat-slide-toggle>\n                            </span>\n                        </td>\n                        <td class=\"text-left btncontainer\">\n                            <button mat-raised-button color=\"primary\" class=\"btnStyle\" (click)=\"updateHotelType(data)\"\n                                style=\"line-height: unset; padding: 0 10px;\">{{'Update'}}</button>&nbsp;\n                                <button mat-raised-button color=\"primary\" class=\"btnStyle\" (click)=\"deleteHotelType(data)\"\n                                style=\"line-height: unset; padding: 0 10px;\">{{'Delete'}}</button>\n                        </td>\n\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n        <div class=\"card-footer pb-0\">\n            <div class=\"d-flex w-100 justify-content-between\">\n                <ngb-pagination [collectionSize]=\"collectionSize\" [maxSize]=\"12\" [rotate]=\"true\" [boundaryLinks]=\"true\" [(page)]=\"page\"\n                    [pageSize]=\"pageSize\">\n                </ngb-pagination>\n                <select class=\"custom-select\" style=\"width: auto\" name=\"pageSize\" [(ngModel)]=\"pageSize\">\n                    <option [ngValue]=\"10\">10 items per page</option>\n                    <option [ngValue]=\"20\">20 items per page</option>\n                    <option [ngValue]=\"50\">50 items per page</option>\n                </select>\n            </div>\n        </div>\n    </form>\n</div>\n";

/***/ }),

