"use strict";
module.exports = "<ul\n  ngbNav\n  #tabs=\"ngbNav\"\n  class=\"tabs-animated custom_tab crs-tab-ui\"\n  [(activeId)]=\"activeIdString\"\n  (navChange)=\"beforeChange($event)\">\n\n  <li [ngbNavItem]=\"'list_hotel_types'\">\n\n    <a ngbNavLink>\n      {{ 'List Stay Types' }}\n    </a>\n\n    <ng-template ngbNavContent>\n      <app-hotel-type-list\n        (toUpdate)=\"triggerTab($event)\">\n      </app-hotel-type-list>\n    </ng-template>\n\n  </li>\n\n  <li [ngbNavItem]=\"'add_hotel_type'\">\n\n    <a ngbNavLink>\n      {{ 'Add/Edit Stay Type' }}\n    </a>\n\n    <ng-template ngbNavContent>\n      <app-add-update-hotel-type\n        (someEvent)=\"triggerTab($event)\"\n        [hotelTypeOne]=\"hotelTypeData\">\n      </app-add-update-hotel-type>\n    </ng-template>\n\n  </li>\n\n</ul>\n\n<div [ngbNavOutlet]=\"tabs\"></div>";

