/***/ 38600:
/*!**************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/hotel-crs/components/season/component/season-list/season-list.component.html?ngResource ***!
  \**************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"container p-0\">\n\n    <div class=\"card-header-tab card-header\">\n        <div class=\"card-header-title font-size-lg text-capitalize font-weight-normal\">\n            <i class=\"header-icon lnr-laptop-phone mr-3 text-muted opacity-6\"> </i> Season List\n        </div>\n    </div>\n\n    <div class=\"text-right m-2\">\n        <!-- <button class=\"btn btn-sm btn-primary mr-1\" (click)=\"onClickAddSeason()\">Add Season</button> -->\n        <button class=\"btn btn-sm btn-primary\" [routerLink]=\"['/hotel-crs-lists']\">Hotel List</button>\n    </div>\n\n    <div class=\"table-responsive\">\n        <table class=\"table table-bordered\">\n            <thead>\n                <tr>\n                    <th class=\"text-left text-nowrap\">Sl No.</th>\n                    <th class=\"text-left text-nowrap\">Seasons</th>\n                    <th class=\"text-left text-nowrap\">From Date</th>\n                    <th class=\"text-left text-nowrap\">To Date</th>\n                    <th class=\"text-left text-nowrap\">Status</th>\n                    <th class=\"text-left text-nowrap\">Actions</th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr *ngFor=\"let season of seasonList | slice: (page - 1) * pageSize : (page - 1) * pageSize + pageSize;let i=index;\">\n                    <td class=\"text-left text-muted\">{{i+1}}.</td>\n                    <td class=\"text-left\">{{season.season_name}}</td>\n                    <td class=\"text-left\">{{season.from_date | date: 'dd/MM/yyyy'}}</td>\n                    <td class=\"text-left\">{{season.to_date | date: 'dd/MM/yyyy'}}</td>\n                    <td>\n                        <span title=\"Slide for Active/Deactive\">\n                            <mat-slide-toggle readonly class=\"example-margin\" [color]=\"''\"\n                                [checked]=\"season['status']\" [(ngModel)]=\"season['status']\" name=\"status{{i}}\"\n                                (click)=\"onStatusUpdate(season,i)\">\n                            </mat-slide-toggle>\n                        </span>\n                    </td>\n                    <td class=\"text-left btncontainer\">\n                        <button (click)=\"updateHotelAmenity(season)\" class=\"btnStyle mr-2\">\n                            <a title=\"Edit\" class=\"p-1\">\n                                <i class=\"fas fa-pencil-alt\"></i>\n                            </a>\n                        </button>\n                        <button (click)=\"deleteSeasonType(season)\" class=\"btnStyle\">\n                            <a title=\"Edit\" class=\"p-1\">\n                                <i class=\"fa fa-trash\"></i>\n                            </a>\n                        </button>\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n    <div class=\"card-footer pb-0\">\n        <div class=\"d-flex w-100 justify-content-between\">\n            <ngb-pagination [collectionSize]=\"collectionSize\" [maxSize]=\"12\" [rotate]=\"true\" [boundaryLinks]=\"true\" [(page)]=\"page\"\n                [pageSize]=\"pageSize\">\n            </ngb-pagination>\n            <select class=\"custom-select\" style=\"width: auto\" name=\"pageSize\" [(ngModel)]=\"pageSize\">\n                <option [ngValue]=\"10\">10 items per page</option>\n                <option [ngValue]=\"20\">20 items per page</option>\n                <option [ngValue]=\"50\">50 items per page</option>\n            </select>\n        </div>\n        </div>\n</div>\n";

/***/ }),

