"use strict";
module.exports = "<hr>\n<div class=\"card\">\n    <form [formGroup]=\"regConfig\" (ngSubmit)=\"onSubmit(regConfig.value)\" class=\"form\">\n        <div class=\"card-header\">\n            <h5 class=\"card-title\">Transfer Markup</h5>\n        </div>\n        <div class=\"card-body\">\n            <table>\n                <div class=\"d-flex flex-row pt-3\">\n                <div class=\"form-group col-sm-4\">\n                    <label for=\"airlines\">Suppliers &nbsp;</label>\n                    <mat-form-field class=\"col-sm-12\"  appearance=\"fill\" style=\"padding-left: 0;\">\n                        <mat-label>Supplier List</mat-label>\n                        <input type=\"text\" placeholder=\"Choose...\"  class=\"text-capitalize\" matInput formControlName=\"suppliers\"\n                            [matAutocomplete]=\"supplier\">\n                        <mat-autocomplete #supplier=\"matAutocomplete\">\n                            <mat-option *ngFor=\"let suppliers of supplierList\"\n                            [value]=\"suppliers.name\"  (click)=\"selectedLocation(suppliers)\">\n                                {{suppliers.name}} \n                            </mat-option>\n                        </mat-autocomplete>\n                    </mat-form-field>\n                </div>\n                <div class=\"form-group col-sm-6\">\n                    <label for=\"agent_id\">Agent&nbsp;</label>\n                    <mat-form-field class=\"col-sm-12\"  appearance=\"fill\" style=\"padding-left: 0;\">\n                        <mat-label>Agent List</mat-label>\n                        <input type=\"text\" placeholder=\"Choose...\"  class=\"text-capitalize\" matInput formControlName=\"agent_id\"\n                            [matAutocomplete]=\"auto\">\n                        <mat-autocomplete class=\"text-uppercase\" #auto=\"matAutocomplete\" (optionSelected)=\"onSelectionChanged($event)\">\n                            <mat-option *ngFor=\"let agent of respAgentData \"\n                                [value]=\"agent.name\" [id]=\"agent.id\">\n                                {{agent.name}} \n                            </mat-option>\n                        </mat-autocomplete>\n                    </mat-form-field>\n                </div>\n                </div>\n            </table>\n            <table>\n                <tr>\n                    <td>\n                        <div class=\"mb-2 mr-sm-2 mb-sm-0 position-relative form-group\">\n                            <label for=\"airlines\" class=\"mr-sm-2\">Markup Type</label>\n                            <div style=\"display: flex;\">\n                                <!-- <div class=\"position-relative form-check\">\n                                    <label class=\"form-check-label\">\n                                        <input value=\"plus\" name=\"markupType\" formControlName=\"markupType\" type=\"radio\"\n                                            class=\"form-check-input\" />\n                                        Plus(+/- {{defaultCurrency}})\n                                    </label>\n                                </div> -->\n                                <div class=\"position-relative form-check\">\n                                    <label class=\"form-check-label\">\n                                        <input value=\"percentage\" formControlName=\"markupType\" checked type=\"radio\"\n                                            class=\"form-check-input\" />\n                                        Percentage(%)\n                                    </label>\n                                </div>\n                            </div>\n                        </div>\n                    </td>\n                    <td>\n                        <div class=\"mb-2 mr-sm-2 mb-sm-0 position-relative form-group\">\n                            <label for=\"markupValue\" class=\"mr-sm-2\">Markup Value</label>\n                            <input formControlName=\"markupValue\" placeholder=\"\" type=\"text\" class=\"form-control\">\n                        </div>\n                    </td>\n                </tr>\n            </table>\n        </div>\n        <div class=\"card-footer customCenter\">\n            <button type=\"reset\" class=\"btn btn-primary\">Reset</button>\n            &nbsp; &nbsp;\n            <button type=\"submit\" class=\"btn btn-primary\">Submit</button>\n        </div>\n    </form>\n</div>\n\n<div class=\"card mt-3\" *ngIf=\"!noData\">\n \n    <table class=\"card-table table\" matSort>\n        <thead>\n            <tr>\n                <th scope=\"col\" class=\"text-center\" *ngFor=\"let header of displayColumn;\">\n                    {{header.value }}\n                </th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr *ngIf=\"noData\">\n                <td colspan=\"11\">\n                    <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\"></mat-spinner>\n                </td>\n            </tr>\n            <tr *ngIf=\"!noData && !respData.length\">\n                <td colspan=\"11\">\n                    <h4 class=\"text-muted text-center\">\n                        No Data Found!\n                    </h4>\n                </td>\n            </tr>\n            <tr *ngFor=\"let data of respData; let i = index\">\n                <td class=\"align-middle text-center\">{{i+1}}.</td>\n                <td class=\"align-middle text-center\">\n                    {{selectedAgentList(data)}}\n                 </td>\n                <td class=\"align-middle text-center\">\n                    \n                     {{getSupplier(data?.supplier) === 'ZBAPINO00011' ? 'Hoppa' : 'Transfer CRS'}}\n                </td>\n         \n                <td class=\"align-middle text-center\">\n                    {{data?.value}}-{{data?.value_type}}\n                </td>\n        \n                <td class=\"align-middle text-center\">\n                    <!-- <button class=\"btn btn-sm btn-primary\" (click)=\"updateMarkup(data)\">\n                        <i class=\"fa fa-edit text-nowrap\">\n                            {{'Update'}}\n                        </i>\n                    </button>&nbsp; -->\n                    <button class=\"btn btn-sm btn-primary\" (click)=\"deleteMarkup(data)\">\n                        <i class=\"fa fa-edit text-nowrap\">\n                            {{'Delete'}}\n                        </i>\n                    </button>\n                </td>\n            </tr>\n        </tbody>\n    </table>\n    </div>\n";

