/***/ 18443:
/*!************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/markup/components/agents-flight/agent-markup-detail/agent-markup-detail.component.html?ngResource ***!
  \************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card p-4\">\n    <h5>Markup List</h5>\n    <form [formGroup]=\"searchForm\">\n        <div class=\"form-row\">\n            <div class=\"form-group col-sm-6\">\n                <label for=\"agent_id\">Agent&nbsp;</label>\n                <mat-form-field class=\"col-sm-12\"  appearance=\"fill\" style=\"padding-left: 0;\">\n                    <mat-label>Agent List</mat-label>\n                    <input type=\"text\" placeholder=\"Choose...\"  class=\"text-capitalize\" matInput formControlName=\"agent_id\"\n                        [matAutocomplete]=\"auto\" [readonly]=\"addOrUpdate=='update'?true:null\" >\n                    <mat-autocomplete class=\"text-uppercase\" #auto=\"matAutocomplete\" (optionSelected)=\"onSelectionChanged($event)\">\n                        <mat-option *ngFor=\"let agent of respData \"\n                            [value]=\"agent.name\" [id]=\"agent.id\">\n                            {{agent.name}} \n                        </mat-option>\n                    </mat-autocomplete>\n                </mat-form-field>\n            </div>\n        </div>\n        <div class=\"customCenter\">\n            <button type=\"submit\" class=\"btnStyle\" (click)=\"onSearchSubmit()\">Search</button> &nbsp;\n            <button type=\"button\" class=\"btnStyle\" (click)=\"onReset()\">Reset</button>\n        </div>\n    </form>\n</div>\n\n\n<div class=\"card mt-3\" *ngIf=\"!noData\">\n    <div class=\"card-header\">\n        <h5 class=\"card-title\" *ngIf=\"agencyDetails\">\n            {{'Agency Name: '+ agencyDetails?.business_name}}\n        </h5>\n    </div>\n    <table class=\"card-table table\" matSort>\n        <thead>\n            <tr>\n                <th scope=\"col\" class=\"text-center\" *ngFor=\"let header of displayColumn;\">\n                    {{header.value }}\n                </th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr *ngIf=\"noData || !markupList.length\">\n                <td colspan=\"11\">\n\n                    <h4 class=\"text-muted text-center\">\n                        No Data Found!\n                    </h4>\n                </td>\n            </tr>\n\n            <tr *ngFor=\"let data of markupList; let i = index\">\n                <td class=\"align-middle text-center\">{{i+1}}.</td>\n                <td class=\"align-middle text-center\">\n                    <img src=\"{{airlineLogoUrl+(data?.flightAirline?.code)+'.gif'}}\"><br>\n                    {{data?.flightAirline?.name}} ({{data?.flightAirline?.code}})\n                </td>\n                <td class=\"align-middle text-center\">\n                    {{data?.value_type}}\n                </td>\n                <td class=\"align-middle text-center\">\n                    {{data?.value}}\n                </td>\n                <td class=\"align-middle text-center\">\n                    <ng-container\n                        *ngFor=\"let item of data?.segment_list | map: getFormattedSegment | keyvalue;let last=last\">\n                        {{item.key}} {{ (item.value)}} <span *ngIf=\"!last\">|</span>\n                    </ng-container>\n                </td>\n                <td class=\"align-middle text-center\">\n                    <button class=\"btn btn-sm btn-primary\" (click)=\"updateMarkup(data)\">\n                        <i class=\"fa fa-edit text-nowrap\">\n                            {{'Update'}}\n                        </i>\n                    </button>&nbsp;\n                    <button class=\"btn btn-sm btn-primary\" (click)=\"deleteMarkup(data)\">\n                        <i class=\"fa fa-edit text-nowrap\">\n                            {{'Delete'}}\n                        </i>\n                    </button>\n                </td>\n            </tr>\n        </tbody>\n    </table>\n</div>";

/***/ }),

