module.exports = "<hr>\n\n<div class=\"\">\n\n  <div class=\"\">\n\n    <ul\n      ngbNav\n      #tabs=\"ngbNav\"\n      class=\"tabs-animated custom_tab\">\n\n      <li [ngbNavItem]=\"'markup_list'\">\n\n        <a ngbNavLink>\n          AGENT MARKUP LIST\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-agent-mark-up-list\n            (toUpdate)=\"triggerTab($event)\">\n          </app-agent-mark-up-list>\n        </ng-template>\n\n      </li>\n\n      <!--\n      <li [ngbNavItem]=\"'markup_detail'\">\n        <a ngbNavLink>\n          <i class=\"fa fa-bank\"></i>&nbsp; MARKUP DETAILS\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-agent-markup-detail\n            (toUpdate)=\"triggerTab($event)\">\n          </app-agent-markup-detail>\n        </ng-template>\n      </li>\n      -->\n\n      <li [ngbNavItem]=\"'default_markup'\">\n\n        <a ngbNavLink>\n          ADD/UPDATE MARKUP\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-agent-markup-add-update\n            [getDataToUpdate]=\"userData\"\n            (toList)=\"triggerTab($event)\">\n          </app-agent-markup-add-update>\n        </ng-template>\n\n      </li>\n\n    </ul>\n\n    <div [ngbNavOutlet]=\"tabs\"></div>\n\n  </div>\n</div>";

