module.exports = "\n<div class=\"card adminInner\">\n    <div class=\"card-header-tab card-header mb-3\">\n      <h5>Bus Markup</h5>\n    </div>\n    <form [formGroup]=\"supplierConfig\"  class=\"form\">\n        \n        <h4 class=\"card-title\">Supplier Markup</h4>\n        \n        <div class=\"card-body p-0\">\n           \n                <div class=\"d-flex flex-row pt-3\">\n          \n                    <div class=\"form-group col-sm-4\">\n                        <label for=\"airlines\">Suppliers &nbsp;</label>\n                        <mat-form-field class=\"col-sm-12\"  appearance=\"fill\" style=\"padding-left: 0;\">\n                            <mat-label>Supplier List</mat-label>\n                            <input type=\"text\" placeholder=\"Choose...\"  class=\"text-capitalize\" matInput formControlName=\"suppliers\"\n                                [matAutocomplete]=\"supplier\">\n                            <mat-autocomplete #supplier=\"matAutocomplete\">\n                                <mat-option *ngFor=\"let suppliers of supplierList\"\n                                [value]=\"suppliers.name\"  (click)=\"selectedLocation(suppliers)\">\n                                    {{suppliers.name}} \n                                </mat-option>\n                            </mat-autocomplete>\n                        </mat-form-field>\n                        <div *ngIf=\"supplierConfig?.get('suppliers')?.touched && supplierConfig?.get('suppliers')?.invalid\" class=\"text-danger\">\n                            Supplier is required.\n                          </div>\n                    </div>\n                    <div class=\"form-group col-sm-4\">\n                      \n                        <input type=\"radio\" value=\"percentage\" formControlName=\"supplier_value_type\" class=\"mb-3\" />\n                        Percentage(%)\n                        <input type=\"text\" onkeypress='return ( event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)' formControlName=\"supplier_value\" class=\"form-control\"\n                            />\n                    </div>\n                    <div class=\"form-group col-sm-4\">\n                        <label>&nbsp;</label>\n                         <button type=\"submit\" class=\"btn btn-primary\"(click)=\"addGeneralMarkup()\">Submit</button>\n                            &nbsp; &nbsp;\n                            <button type=\"reset\" class=\"btn btn-secondary\">Reset</button>\n\n                    </div>\n             \n                </div>\n            \n        </div>\n       \n    </form>\n    <form [formGroup]=\"regConfig\"  class=\"form\">\n\n        <div class=\"card-body p-0\">\n           \n                <h4 class=\"card-title\">Supplier Citywise Markup</h4>\n                <div class=\"d-flex flex-row pt-3\">\n                    <div class=\"form-group col-sm-4\">\n                        <label for=\"airlines\">Suppliers &nbsp;</label>\n                        <mat-form-field class=\"col-sm-12\"  appearance=\"fill\" style=\"padding-left: 0;\">\n                            <mat-label>Supplier List</mat-label>\n                            <input type=\"text\" placeholder=\"Choose...\"  class=\"text-capitalize\" matInput formControlName=\"suppliers\"\n                                [matAutocomplete]=\"supplier\">\n                            <mat-autocomplete #supplier=\"matAutocomplete\">\n                                <mat-option *ngFor=\"let suppliers of supplierList\"\n                                [value]=\"suppliers.name\"  (click)=\"selectedLocation(suppliers)\">\n                                    {{suppliers.name}} \n                                </mat-option>\n                            </mat-autocomplete>\n                        </mat-form-field>\n                        <div *ngIf=\"regConfig?.get('suppliers')?.touched && regConfig?.get('suppliers')?.invalid\" class=\"text-danger\">\n                            Supplier is required.\n                          </div>\n                    </div>\n                    <!-- <div class=\"form-group col-sm-4 mb-3\">\n                        <label class=\" control-label\">\n                            Country\n             \n                        </label>\n                        <select formControlName=\"core_country_id\" class=\"form-control\" (change)=\"getCityListAuto($event)\"\n                            >\n                            <option value=\"\" disabled selected>Select Country</option>\n                            <option *ngFor=\"let coreCountry of coreCountryList\" [value]=\"coreCountry.countryCode\">\n                                {{coreCountry.countryName}}\n                            </option>\n                        </select>\n              \n                    </div>\n                    <div class=\"form-group col-sm-4\">\n                       \n                        <input type=\"radio\" value=\"percentage\" formControlName=\"country_type\" />\n                        Percentage(%)\n                        <input type=\"text\" onkeypress='return ( event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)' formControlName=\"country_value\" class=\"form-control\"\n                            />\n                    </div> -->\n\n                </div>\n           \n           \n                <div *ngIf=\"!cities.controls.length\"class=\"d-flex flex-row pt-3\">\n                    <div class=\"form-group col-sm-4 mb-3\">\n                        <label class=\"control-label\">\n                            City\n                            <!-- <span class=\"text-danger\">*</span> -->\n                        </label>\n                        <select formControlName=\"city_name\" class=\"form-control\"(ngModelChange)=\"onCityChange($event)\"\n                           >\n                            <option value=\"\" disabled selected>Select City</option>\n                            <option *ngFor=\"let coreCity of coreCityList\" [value]=\"coreCity.Id\">\n                                {{coreCity.cityName}}\n                            </option>\n                        </select>\n                        <!-- <div *ngIf=\"submittedHotel && hotel.city_name.errors\" class=\"invalid-feedback\">\n                            <div *ngIf=\"hotel.city_name.errors.required\">City is required</div>\n                        </div> -->\n                    </div>\n                    <div class=\"form-group col-sm-4\">\n                        <div class=\"row mb-2 ml-2\">\n                            <input type=\"radio\" value=\"percentage\" formControlName=\"city_value_type\" />\n                            Percentage(%)\n                        </div>\n                       \n                        <input type=\"text\" onkeypress='return ( event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)' formControlName=\"city_value\" class=\"form-control\"\n                            />\n                    </div>\n\n                    <div class=\"form-group col-sm-4\">\n                          <label>&nbsp;</label>\n                        <button type=\"submit\" class=\"btn btn-primary\"(click)=\"onSubmit()\">Submit</button>\n            &nbsp; &nbsp;\n            <button type=\"reset\" class=\"btn btn-secondary\">Reset</button>\n\n\n                    </div>\n\n                </div>\n           \n                <div *ngIf=\"cities.controls.length\" >\n                <div formArrayName=\"cities\" *ngFor=\"let city of cities.controls; let i = index\">\n                    <div [formGroupName]=\"i\" class=\"d-flex flex-row pt-3\">\n                      <div class=\"form-group col-sm-4 mb-3\">\n                        <label class=\"control-label\">City <span class=\"text-danger\">*</span></label>\n                        <select formControlName=\"city_name\" class=\"form-control\">\n                          <option value=\"\" disabled selected>Select City</option>\n                          <option *ngFor=\"let coreCity of coreCityList\" [value]=\"coreCity.Id\">\n                            {{coreCity.cityName}}\n                          </option>\n                        </select>\n                      </div>\n                      <div class=\"form-group col-sm-4\">\n                        <input type=\"radio\" value=\"percentage\" formControlName=\"city_value_type\" /> Percentage(%)\n                        <input type=\"text\" onkeypress='return ( event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)' formControlName=\"city_value\" class=\"form-control\" />\n                      </div>\n                                   <div class=\"form-group col-sm-4\">\n                          <label>&nbsp;</label>\n                        <button type=\"submit\" class=\"btn btn-primary\"(click)=\"onSubmit()\">Submit</button>\n            &nbsp; &nbsp;\n            <button type=\"reset\" class=\"btn btn-secondary\">Reset</button>\n\n\n                    </div>\n                    </div>\n                  </div>\n                  </div>\n           \n        \n        </div>\n       \n    </form>\n</div>\n\n<div class=\"card adminInner mt-3\" *ngIf=\"!noData\">\n    \n        <h4 class=\"card-title\">Stay Markup List</h4>\n    \n    <table class=\"table table-borderless table-striped table-hover\" matSort>\n        <thead>\n            <tr>\n                <th scope=\"col\" class=\"text-center\" *ngFor=\"let header of displayColumn;\">\n                    {{header.value }}\n                </th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr *ngIf=\"noData\">\n                <td colspan=\"11\">\n                    <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\"></mat-spinner>\n                </td>\n            </tr>\n            <tr *ngIf=\"!noData && (respData == null || !respData.length) \">\n                <td colspan=\"11\">\n                    <h4 class=\"text-muted text-center\">\n                        No Data Found!\n                    </h4>\n                </td>\n            </tr>\n            <tr *ngFor=\"let data of respData; let i = index\">\n                <td class=\"align-middle text-center\">{{i+1}}.</td>\n             \n                <td class=\"align-middle text-center\">\n                    \n                    {{selectedSupplierList(data)}}\n                </td>\n         \n                <td class=\"align-middle text-center\">\n                    {{ data?.value}}-{{ data?.value_type}}\n                </td>\n          \n                <!-- <td class=\"align-middle text-center\">\n                    <ng-container *ngIf=\"data?.supplier\">\n                      <ng-container *ngFor=\"let item of getFormattedSegment(data.supplier)\">\n                \n                        <ng-container *ngIf=\"item?.country\">\n                          <ng-container *ngFor=\"let countryEntry of item.country | keyvalue\">\n                            <div>\n                              Country: {{ countryEntry.value.name }} |\n                              Value: {{ countryEntry.value.value }} -\n                              {{ countryEntry.value.value_type || '--'}}\n                            </div>\n                          </ng-container>\n                        </ng-container>\n                      </ng-container>\n                    </ng-container>\n                  </td> -->\n                  \n                  <td class=\"align-middle text-center\">\n                    <ng-container *ngIf=\"data?.supplier\">\n                      <ng-container *ngFor=\"let item of getFormattedSegment(data.supplier)\">\n                        <!-- City Details -->\n                        <ng-container *ngIf=\"item?.city\">\n                          <ng-container *ngFor=\"let cityEntry of item.city | keyvalue\">\n                            <div>\n                              City: {{ cityEntry.value.name }} |\n                              Value: {{ cityEntry.value.value }} -\n                              {{ cityEntry.value.value_type }}\n                            </div>\n                          </ng-container>\n                        </ng-container>\n                      </ng-container>\n                    </ng-container>\n                  </td>\n                  \n        \n                <td class=\"align-middle text-center\">\n                    <label>&nbsp;</label>\n                    <button class=\"btn btn-sm btn-primary\" (click)=\"updateMarkup(data)\">\n                      \n                            {{'Update'}}\n                     \n                    </button>&nbsp;\n                    <button class=\"btn btn-sm btn-secondary\" (click)=\"deleteMarkup(data)\">\n                        \n                            {{'Delete'}}\n                      \n                    </button>\n                </td>\n            </tr>\n        </tbody>\n    </table>\n    </div>";

