module.exports = "<div class=\"\">\n    <hr>\n    <div class=\"card mb-3\">\n        <form [formGroup]=\"regConfig\" autocomplete=\"off\">\n            <div>\n                <!-- <div class=\"d-flex flex-row pt-3\">\n                    <div class=\"form-group col-sm-4\">\n                        <label for=\"airlines\">Suppliers &nbsp;</label>\n                        <mat-form-field class=\"col-sm-12\"  appearance=\"fill\" style=\"padding-left: 0;\">\n                            <mat-label>Supplietr List</mat-label>\n                            <input type=\"text\" placeholder=\"Choose...\"  class=\"text-capitalize\" matInput formControlName=\"suppliers\"\n                                [matAutocomplete]=\"supplier\">\n                            <mat-autocomplete #supplier=\"matAutocomplete\">\n                                <mat-option *ngFor=\"let suppliers of supplierList\"\n                                [value]=\"suppliers.name\">\n                                    {{suppliers.name}} \n                                </mat-option>\n                            </mat-autocomplete>\n                        </mat-form-field>\n                    </div>\n\n                    <div class=\"form-group col-sm-3\">\n                        <input type=\"radio\" value=\"plus\" formControlName=\"supplier_value_type\"  /> Plus(+/-\n                        {{defaultCurrency}})\n                        <input type=\"radio\" value=\"percentage\" formControlName=\"supplier_value_type\" />\n                        Percentage(%)\n                        <input type=\"text\" onkeypress='return ( event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)' formControlName=\"supplier_value\" class=\"form-control\"\n                            />\n                    </div>\n\n                </div> -->\n                <div class=\"d-flex flex-row pt-3\">\n                    <div class=\"form-group col-sm-4\">\n                        <label for=\"airlines\">Airlines &nbsp;</label>\n                        <mat-form-field class=\"col-sm-12\"  appearance=\"fill\" style=\"padding-left: 0;\">\n                            <mat-label>Airline List</mat-label>\n                            <input type=\"text\" placeholder=\"Choose...\"  class=\"text-capitalize\" matInput formControlName=\"airlines\"\n                                [matAutocomplete]=\"autoAirline\" [readonly]=\"addOrUpdate=='update'?true:null\">\n                            <mat-autocomplete #autoAirline=\"matAutocomplete\" (optionSelected)=\"checkAirline($event)\">\n                                <mat-option *ngFor=\"let airline of filteredAirline  | async\"\n                                    [value]=\"airline.name +' '+' ('+ airline.code +')'\" [id]=\"airline.id\">\n                                    {{airline.name}} ({{airline.code}})\n                                </mat-option>\n                            </mat-autocomplete>\n                        </mat-form-field>\n                    </div>\n\n                    <div class=\"form-group col-sm-3 row\">\n                        <!-- <input type=\"radio\" value=\"plus\" formControlName=\"value_type\"  /> Plus(+/-\n                        {{defaultCurrency}}) -->\n                        <input style=\"display: none;\" type=\"radio\" value=\"percentage\" formControlName=\"value_type\" />\n                        Percentage(%)\n                        <input type=\"text\" onkeypress='return ( event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)' formControlName=\"value\" class=\"form-control\"\n                            />\n                    </div>\n\n                </div>\n\n                <div formArrayName=\"segments\">\n                    <div class=\"d-flex flex-row\" style=\"position: relative;\"\n                        *ngFor=\"let segment of segments()?.controls; let i=index;let last=last\" [formGroupName]=\"i\">\n\n                        <div class=\"form-group col-md-4\">\n                            <label for=\"from_airport_name\">From</label>\n                            <input formControlName=\"from_airport_name\" type=\"text\" class=\"form-control text-capitalize\"\n                                placeholder=\"From Airport\" id=\"appReference\"\n                                (keyup)=\"getAutoCompleteLocations($event,'from', i)\" list=\"dynamicLocationsOrigin\">\n                            <ul class=\"droplocations\" id=\"dynmicLocations\" *ngIf=\"i==selectedCity\">\n                                <li *ngFor=\"let location of locationsOrigin\" (click)=\"selectedOrigin(location, i)\">\n                                    <i class=\"fal fa-map-marker-alt\"></i>\n                                    {{location | map: getAirportLocation}}\n                                </li>\n                            </ul>\n                        </div>\n\n                        <div class=\"form-group col-md-4\">\n                            <label for=\"to_airport_name\">To</label>\n                            <input formControlName=\"to_airport_name\" type=\"text\" class=\"form-control text-capitalize\"\n                                placeholder=\"To Airport\" id=\"phone\" (keyup)=\"getAutoCompleteLocations($event,'to', i)\"\n                                list=\"dynamicLocationsDest\">\n                            <ul class=\"droplocations\" id=\"dynmicLocations\" *ngIf=\"i==selectedCity\">\n                                <li *ngFor=\"let location of locationsDestination\" (click)=\"selectedDest(location, i)\">\n                                    <i class=\"fal fa-map-marker-alt\"></i>\n                                    {{location | map: getAirportLocation}}\n                                </li>\n                            </ul>\n                        </div>\n\n                        <div class=\"form-group col-md-3 row mt-2\">\n                            <div>\n                                <!-- <input type=\"radio\" value=\"plus\" formControlName=\"value_type\" name=\"value_type\"    /> Plus(+\n                                {{defaultCurrency}}) -->\n                                <input type=\"radio\" style=\"display: none;\" value=\"percentage\" formControlName=\"value_type\" name=\"value_type\"  />\n                                Percentage(%)\n                                <input type=\"text\" onkeypress='return ( event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)' formControlName=\"value\" class=\"form-control\"\n                                     />\n                            </div>\n                        </div>\n\n                        <div class=\"col-md-1 d-flex\">\n\n                            <!-- <label for=\"city\" class=\"col-2 col-form-label opacity-0\"></label> -->\n                            <button class=\"col-sm-1\" class=\"rmvBtn\" (click)=\"removeSegment(i)\">\n                                <i class=\"fas fa-trash\"></i>\n                            </button>\n\n                            <!-- <label for=\"city\" class=\"col-2 col-form-label opacity-0\"></label> -->\n                            <div class=\"col-4 d-flex add-more-btn\" *ngIf=\"last\">\n                                <button type=\"button\" class=\"btn btn-primary\" (click)=\"addMoreSegments()\">\n                                    <i class=\"fa fa-plus\" aria-hidden=\"true\"></i>\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n                <table class=\"table\">\n                    <tr>\n                        <td>\n                            <div id=\"allbtn\" class=\"customCenter\">\n                                <span class=\"p-1\">\n                                    <button (click)=\"onSubmit()\" class=\"btn btn-primary p-1\">{{this.addOrUpdate |\n                                        uppercase}}</button>\n                                </span>\n                                <span class=\"p-1\">\n                                    <button type=\"reset\" class=\"btn btn-primary p-1\" (click)=\"reset()\">RESET</button>\n                                </span>\n                            </div>\n                        </td>\n                    </tr>\n                </table>\n            </div>\n        </form>\n    </div>\n</div>";

