module.exports = "<hr>\n\n<div class=\"\">\n  <div class=\"\">\n\n    <ul\n      ngbNav\n      #tabs=\"ngbNav\"\n      class=\"tabs-animated custom_tab\">\n\n      <li [ngbNavItem]=\"'markup_detail'\">\n\n        <a ngbNavLink>\n          MARKUP DETAILS\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-agent-b2c-markup-detail\n            (toUpdate)=\"triggerTab($event)\">\n          </app-agent-b2c-markup-detail>\n        </ng-template>\n\n      </li>\n\n      <li [ngbNavItem]=\"'default_markup'\">\n\n        <a ngbNavLink>\n          ADD/UPDATE MARKUP\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-agent-b2c-markup-add-update\n            [getDataToUpdate]=\"userData\"\n            (toList)=\"triggerTab($event)\">\n          </app-agent-b2c-markup-add-update>\n        </ng-template>\n\n      </li>\n\n      <li [ngbNavItem]=\"'default_supplier'\">\n\n        <a ngbNavLink>\n          Supplier Update\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-supplier-markup-update\n            [getSupplierToUpdate]=\"userData\"\n            (supplierListdata)=\"triggerTab($event)\">\n          </app-supplier-markup-update>\n        </ng-template>\n\n      </li>\n\n      <li [ngbNavItem]=\"'default_supplier_list'\">\n\n        <a ngbNavLink>\n          Supplier List\n        </a>\n\n        <ng-template ngbNavContent>\n          <app-supplir-markup-list\n            (toUpdateSupplier)=\"triggerTab($event)\">\n          </app-supplir-markup-list>\n        </ng-template>\n\n      </li>\n\n    </ul>\n\n    <div [ngbNavOutlet]=\"tabs\"></div>\n\n  </div>\n</div>";

