module.exports = "<div class=\"card adminInner\">\n  <div class=\"card-header-tab card-header mb-3\">\n    <h5>Wellness Markup</h5>\n  </div>\n\n  <form [formGroup]=\"supplierConfig\" class=\"form\">\n    <h4 class=\"card-title\">Supplier Markup</h4>\n\n    <div class=\"card-body p-0\">\n      <div class=\"d-flex flex-row pt-3\">\n        <div class=\"form-group col-sm-4\">\n          <label>Suppliers &nbsp;</label>\n\n          <mat-form-field class=\"col-sm-12\" appearance=\"fill\" style=\"padding-left: 0;\">\n            <mat-label>Supplier List</mat-label>\n            <input\n              type=\"text\"\n              placeholder=\"Choose...\"\n              class=\"text-capitalize\"\n              matInput\n              formControlName=\"suppliers\"\n              [matAutocomplete]=\"supplierGeneral\"\n            />\n\n            <mat-autocomplete #supplierGeneral=\"matAutocomplete\">\n              <mat-option\n                *ngFor=\"let suppliers of supplierList\"\n                [value]=\"suppliers.name\"\n                (click)=\"selectedLocation(suppliers)\"\n              >\n                {{ suppliers.name }}\n              </mat-option>\n            </mat-autocomplete>\n          </mat-form-field>\n\n          <div\n            *ngIf=\"supplierConfig?.get('suppliers')?.touched && supplierConfig?.get('suppliers')?.invalid\"\n            class=\"text-danger\"\n          >\n            Supplier is required.\n          </div>\n        </div>\n\n        <div class=\"form-group col-sm-4\">\n          <input\n            type=\"radio\"\n            value=\"percentage\"\n            formControlName=\"supplier_value_type\"\n            class=\"mb-3\"\n          />\n          Percentage(%)\n\n          <input\n            type=\"text\"\n            onkeypress='return (event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)'\n            formControlName=\"supplier_value\"\n            class=\"form-control\"\n          />\n        </div>\n\n        <div class=\"form-group col-sm-4\">\n          <label>&nbsp;</label>\n          <button type=\"button\" class=\"btn btn-primary\" (click)=\"addGeneralMarkup()\">Submit</button>\n          &nbsp;&nbsp;\n          <button type=\"reset\" class=\"btn btn-secondary\">Reset</button>\n        </div>\n      </div>\n    </div>\n  </form>\n\n  <form [formGroup]=\"regConfig\" class=\"form\">\n    <div class=\"card-body p-0\">\n      <h4 class=\"card-title\">Supplier Citywise Wellness Markup</h4>\n\n      <div class=\"d-flex flex-row pt-3\">\n        <div class=\"form-group col-sm-4\">\n          <label>Suppliers &nbsp;</label>\n\n          <mat-form-field class=\"col-sm-12\" appearance=\"fill\" style=\"padding-left: 0;\">\n            <mat-label>Supplier List</mat-label>\n            <input\n              type=\"text\"\n              placeholder=\"Choose...\"\n              class=\"text-capitalize\"\n              matInput\n              formControlName=\"suppliers\"\n              [matAutocomplete]=\"supplierCity\"\n            />\n\n            <mat-autocomplete #supplierCity=\"matAutocomplete\">\n              <mat-option\n                *ngFor=\"let suppliers of supplierList\"\n                [value]=\"suppliers.name\"\n                (click)=\"selectedLocation(suppliers)\"\n              >\n                {{ suppliers.name }}\n              </mat-option>\n            </mat-autocomplete>\n          </mat-form-field>\n\n          <div\n            *ngIf=\"regConfig?.get('suppliers')?.touched && regConfig?.get('suppliers')?.invalid\"\n            class=\"text-danger\"\n          >\n            Supplier is required.\n          </div>\n        </div>\n      </div>\n\n      <div *ngIf=\"!cities.controls.length\" class=\"d-flex flex-row pt-3\">\n        <div class=\"form-group col-sm-4 mb-3\">\n          <label class=\"control-label\">City</label>\n\n          <select\n            formControlName=\"city_name\"\n            class=\"form-control\"\n            (ngModelChange)=\"onCityChange($event)\"\n          >\n            <option value=\"\" disabled selected>Select City</option>\n            <option *ngFor=\"let coreCity of coreCityList\" [value]=\"coreCity.Id\">\n              {{ coreCity.cityName }}\n            </option>\n          </select>\n        </div>\n\n        <div class=\"form-group col-sm-4\">\n          <div class=\"row mb-2 ml-2\">\n            <input type=\"radio\" value=\"percentage\" formControlName=\"city_value_type\" />\n            Percentage(%)\n          </div>\n\n          <input\n            type=\"text\"\n            onkeypress='return (event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)'\n            formControlName=\"city_value\"\n            class=\"form-control\"\n          />\n        </div>\n\n        <div class=\"form-group col-sm-4\">\n          <label>&nbsp;</label>\n          <button type=\"button\" class=\"btn btn-primary\" (click)=\"onSubmit()\">Submit</button>\n          &nbsp;&nbsp;\n          <button type=\"reset\" class=\"btn btn-secondary\">Reset</button>\n        </div>\n      </div>\n\n      <div *ngIf=\"cities.controls.length\">\n        <div formArrayName=\"cities\" *ngFor=\"let city of cities.controls; let i = index\">\n          <div [formGroupName]=\"i\" class=\"d-flex flex-row pt-3\">\n            <div class=\"form-group col-sm-4 mb-3\">\n              <label class=\"control-label\">\n                City <span class=\"text-danger\">*</span>\n              </label>\n\n              <select formControlName=\"city_name\" class=\"form-control\">\n                <option value=\"\" disabled selected>Select City</option>\n                <option *ngFor=\"let coreCity of coreCityList\" [value]=\"coreCity.Id\">\n                  {{ coreCity.cityName }}\n                </option>\n              </select>\n            </div>\n\n            <div class=\"form-group col-sm-4\">\n              <input type=\"radio\" value=\"percentage\" formControlName=\"city_value_type\" />\n              Percentage(%)\n\n              <input\n                type=\"text\"\n                onkeypress='return (event.charCode >= 48 && event.charCode <= 57) || (event.charCode == 45 && this.value.indexOf(\"-\") === -1 && this.selectionStart == 0)'\n                formControlName=\"city_value\"\n                class=\"form-control\"\n              />\n            </div>\n\n            <div class=\"form-group col-sm-4\">\n              <label>&nbsp;</label>\n              <button type=\"button\" class=\"btn btn-primary\" (click)=\"onSubmit()\">Submit</button>\n              &nbsp;&nbsp;\n              <button type=\"reset\" class=\"btn btn-secondary\">Reset</button>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </form>\n</div>\n\n<div class=\"card adminInner mt-3\" *ngIf=\"!noData\">\n  <h4 class=\"card-title\">Wellness Markup List</h4>\n\n  <table class=\"table table-borderless table-striped table-hover\" matSort>\n    <thead>\n      <tr>\n        <th scope=\"col\" class=\"text-center\" *ngFor=\"let header of displayColumn\">\n          {{ header.value }}\n        </th>\n      </tr>\n    </thead>\n\n    <tbody>\n      <tr *ngIf=\"noData\">\n        <td colspan=\"11\">\n          <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\"></mat-spinner>\n        </td>\n      </tr>\n\n      <tr *ngIf=\"!noData && (respData == null || !respData.length)\">\n        <td colspan=\"11\">\n          <h4 class=\"text-muted text-center\">No Data Found!</h4>\n        </td>\n      </tr>\n\n      <tr *ngFor=\"let data of respData; let i = index\">\n        <td class=\"align-middle text-center\">{{ i + 1 }}.</td>\n\n        <td class=\"align-middle text-center\">\n          {{ selectedSupplierList(data) }}\n        </td>\n\n        <td class=\"align-middle text-center\">\n          {{ data?.value }}-{{ data?.value_type }}\n        </td>\n\n        <td class=\"align-middle text-center\">\n          <ng-container *ngIf=\"data?.supplier\">\n            <ng-container *ngFor=\"let item of getFormattedSegment(data.supplier)\">\n              <ng-container *ngIf=\"item?.city\">\n                <ng-container *ngFor=\"let cityEntry of item.city | keyvalue\">\n                  <div>\n                    City: {{ cityEntry.value.name }} |\n                    Value: {{ cityEntry.value.value }} -\n                    {{ cityEntry.value.value_type }}\n                  </div>\n                </ng-container>\n              </ng-container>\n            </ng-container>\n          </ng-container>\n        </td>\n\n        <td class=\"align-middle text-center\">\n          <button class=\"btn btn-sm btn-primary\" (click)=\"updateMarkup(data)\">\n            Update\n          </button>\n          &nbsp;\n          <button class=\"btn btn-sm btn-secondary\" (click)=\"deleteMarkup(data)\">\n            Delete\n          </button>\n        </td>\n      </tr>\n    </tbody>\n  </table>\n</div>";

