/***/ 27639:
/*!******************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/master-balance/modals/process-transaction-balance/process-transaction-balance.component.html?ngResource ***!
  \******************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<!-- <p>process-transaction-balance works!</p> -->\n<h2 mat-dialog-title>{{' Please Verify Before You Process This Transaction Request'}}</h2>\n<form [formGroup]=\"regConf\">\n    <mat-dialog-content>\n        <div class=\"row m-0 alert alert-info\">\n            <div class=\"col-12 p-0\">\n                <span> Company Name {{data.authUser.business_name}} (ID:&nbsp; {{data.authUser.uuid}}) </span> <br>\n                <span>Prime User Name:&nbsp; {{data.authUser.first_name}}&nbsp;{{data.authUser.last_name}} </span> <br>\n                <!-- <span>Agent Name:&nbsp; {{ data['requested_from'] ? data['requested_from'] : 'Agent'}}</span> <br> -->\n                <span>Amount:&nbsp; {{data['amount']}}&nbsp;({{data['currency']}}) </span> <br>\n                <span>Processed By:&nbsp; {{ data['processedby']}} </span> <br>\n            </div>\n        </div>\n        <div class=\"row m-0\">\n            <div class=\"col-12 my-3\">\n                <div class=\"form-gorup row mb-2\">\n                    <label for=\"remarks\" class=\"col-2 col-form-label\">Amount</label>\n                    <input autocomplete=\"off\" formControlName=\"amount\" class=\"col-10 form-control\" name=\"amount\" id=\"amount\" type=\"number\" step=\"0.01\" max=\"{{data.amount}}\" (keyup)=\"validateAmount()\" />\n                    <small class=\"col-10 offset-2 text-danger\" *ngIf=\"regConf?.get('amount')?.hasError('invalidNumber')\">\n                    Please enter a valid number\n                    </small>\n                    <small class=\"col-10 offset-2 text-danger\" *ngIf=\"regConf?.get('amount')?.hasError('exceedsMaxAmount')\">\n                    Amount cannot exceed {{data.amount}}\n                    </small>\n                    <small class=\"col-10 offset-2 text-danger\" *ngIf=\"regConf?.get('amount')?.hasError('negativeAmount')\">\n                    Amount must be positive\n                    </small>\n                </div>\n                <div class=\"form-gorup row mb-2\">\n                    <label for=\"status\" class=\"col-2 col-form-label\">Status</label>\n                    <select formControlName=\"status\" name=\"status\" id=\"status\" class=\"col-10 form-control\">\n                        <option value=\"pending\" selected>Pending</option>\n                        <option value=\"accepted\">Accepted</option>\n                        <option value=\"rejected\">Rejected</option>\n                    </select>\n                </div>\n                <div class=\"form-gorup row\">\n                    <label for=\"remarks\" class=\"col-2 col-form-label\">Remarks</label>\n                    <textarea formControlName=\"remarks\" class=\"col-10 form-control\" name=\"remarks\" id=\"remarks\" rows=\"2\"></textarea>\n                </div>\n            </div>\n        </div>\n\n    </mat-dialog-content>\n\n    <mat-dialog-actions>\n        <div class=\"d-flex justify-content-end\">\n            <button class=\"btn btn-primary mr-2\" (click)=\"close()\">Close</button>\n            <button class=\"btn btn-primary\" (click)=\"save()\">Confirm</button>\n        </div>\n    </mat-dialog-actions>\n</form>";

/***/ }),

