/***/ 96738:
/*!****************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/other/all-notification/all-notification.component.html?ngResource ***!
  \****************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card mb-3\">\n    <div class=\"card-header-tab card-header\">\n        <div class=\"card-header-title font-size-lg text-capitalize font-weight-normal\">\n            <i class=\"header-icon lnr-laptop-phone mr-3 text-muted opacity-6\"> </i>\n            {{'Event Notifications List'}}\n        </div>\n    </div>\n    <div class=\"table-responsive\">\n        <table class=\"align-middle mb-0 table table-borderless table-striped table-hover\">\n            <thead>\n                <tr class=\"p-2\">\n                    <th scope=\"col\" class=\"text-left\" *ngFor=\"let header of displayColumn;\">\n                        {{header.value }} </th>\n                </tr>\n            </thead>\n            <tbody>\n                <ng-template #notShow>\n                    <tr class=\"p-2\" *ngFor=\"let data of respData; let i=index;\">\n                        <td class=\"text-left text-muted\">{{i+1}}.</td>\n                        <td class=\"text-left\">\n                            <div class=\"row\">\n                                <div class=\"col-1 customCenter\">\n                                    <span class=\"bg-info p-1 text-white\"> <i class=\"{{data['event_icon']}} p-1\"></i> </span>\n                                </div>\n                                <div class=\"col-11 pl-0\">\n                                    <div class=\"\" [innerHTML]=\"data['event_title']\"></div>\n                                    \n                                    <div [innerHTML]=\"data['event_description']\"></div>\n                                </div>\n                            </div>\n                        </td>\n                        <td class=\"text-left\">\n                            <button mat-raised-button color=\"primary\"\n                                style=\"height: 28px; line-height: unset; padding: 0 10px;\">{{'View Details'}}</button>\n                        </td>\n                    </tr>\n                </ng-template>\n                <tr *ngIf=\"noData; else notShow\">\n                    <td colspan=\"7\" class=\"text-center\">\n                        <mat-spinner [diameter]=\"30\" mode=\"indeterminate\" style=\"margin: 0 auto;\"></mat-spinner>\n                        No Data Found\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n</div>";

/***/ }),

/***/ 67521:
/*!*************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/payment/components/account-ledger/account-ledger.component.html?ngResource ***!
  \*************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<button class=\"btnStyle\" style=\"margin-bottom: 10px;\">Account Ledger</button>\n<app-search-account-system></app-search-account-system>\n<div class=\"exportWrapper\">\n    <p *ngIf=\"respData\">Total {{respData.length}} transaction found</p>\n    <button type=\"button\">PDF</button>\n    <button type=\"button\">Export to Excel</button>\n    <button type=\"button\"><i class=\"fas fa-envelope\"></i>&nbsp; Email</button>\n</div>\n\n<div class=\"card\">\n    <div class=\"card-body\">\n        <!-- <app-dynamic-table [data]=\" tabsData \"></app-dynamic-table> -->\n        <div class=\"mb-3\">\n\n            <form>\n                <div class=\"p-2\">\n                    <div class=\"form-group form-inline mb-0\">\n                        Full text search:\n                        <input class=\"form-control ml-2\" type=\"text\" name=\"searchTerm\"\n                            (keyup)=\"applyFilter($event.target.value)\" />\n                    </div>\n                </div>\n                <div class=\"table-responsive\">\n                    <table class=\"table table-borderless table-striped table-hover\" matSort\n                        (matSortChange)=\"sortData($event)\">\n                        <thead>\n                            <tr>\n                                <th scope=\"col\" class=\"text-left text-nowrap\" *ngFor=\"let header of displayColumn;\"\n                                    mat-sort-header=\"{{header.key}}\">\n                                    {{header.value }} </th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr *ngIf=\"noData\">\n                                <td colspan=\"11\">\n                                    <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\">\n                                    </mat-spinner>\n                                </td>\n                            </tr>\n\n                            <tr\n                                *ngFor=\"let data of respData | slice: (page - 1) * pageSize : (page - 1) * pageSize + pageSize; let i=index;\">\n                                <td class=\"text-left text-muted\">{{i+1}}.</td>\n                                <td class=\"text-left\"> {{data['transaction_date'] | date:\n                                    \"d-MMM-y\"}} </td>\n                                <td class=\"text-left\"> {{data['reference_number']}} </td>\n                                <td class=\"text-left\"> {{data['payment_type']}} </td>\n                                <td class=\"text-left\">{{data['opening_balance']}} </td>\n                                <td class=\"text-left\"> {{data['description']}} </td>\n                                <td class=\"text-left\"> {{data['debit_amount']}} </td>\n                                <td class=\"text-left\"> {{data['credit_amount']}} </td>\n                                <td class=\"text-left\"> {{data['closing_balance']}} </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                <div class=\"card-footer pb-0\">\n                    <div class=\"d-flex w-100 justify-content-between\">\n                        <ngb-pagination [collectionSize]=\"collectionSize\" [(page)]=\"page\" [pageSize]=\"pageSize\">\n                        </ngb-pagination>\n                        <select class=\"custom-select\" style=\"width: auto\" name=\"pageSize\" [(ngModel)]=\"pageSize\">\n                            <option [ngValue]=\"2\">2 items per page</option>\n                            <option [ngValue]=\"4\">4 items per page</option>\n                            <option [ngValue]=\"6\">6 items per page</option>\n                        </select>\n                    </div>\n                </div>\n            </form>\n        </div>\n\n    </div>\n</div>";

/***/ }),

