"use strict";
module.exports = "<!-- <p>invoice-management works!</p> -->\n<div class=\"topSectionContainer\">\n    <button class=\"btnStyle\">INVOICE MANAGEMENT</button>\n    <div class=\"dropdownStyle\">\n        <label for=\"module\" style=\"color: #082B3A;\">MODULE TYPE</label>\n        <select name=\"module\" id=\"module\">\n            <option value=\"volvo\">Flight</option>\n            <option value=\"saab\">Hotel</option>\n            <option value=\"opel\">Insurance</option>\n        </select>\n    </div>\n\n</div>\n\n<!-- <p>history-deposit-request works!</p> -->\n<div class=\"row card\">\n    <div class=\"col-md-12 col-lg-12\">\n       <form class=\"clearfix\">\n          <!-- <div class=\"p-2 customBorder\">\n             <div class=\"form-group form-inline mb-0\">\n                Full text search:\n                <input class=\"form-control ml-2\" type=\"text\" name=\"searchTerm\"/>\n             </div>\n          </div> -->\n          <div class=\"row col-md-12 col-lg-12 m-0 p-0\">\n             <table style=\"table-layout: fixed; width: 100%;\">\n                <tr>\n                   <td>\n                      <div class=\"table-responsive\">\n                         <table class=\"align-middle mb-0 table table-borderless table-striped table-hover\"\n                            matSort (matSortChange)=\"sortData($event)\">\n                            <thead>\n                               <tr class=\"p-2\">\n                                  <th scope=\"col\" class=\"text-nowrap\" *ngFor=\"let header of displayColumn;\"\n                                     mat-sort-header=\"{{header.key}}\">\n                                     {{header.value }} \n                                  </th>\n                               </tr>\n                            </thead>\n                            <tbody>\n                               <tr *ngIf=\"noData\">\n                                  <td colspan=\"12\">\n                                     <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\"\n                                        mode=\"indeterminate\"></mat-spinner>\n                                  </td>\n                               </tr>\n                               <!-- <tr class=\"p-2\"\n                                  *ngFor=\"let balance of respData | slice: (page - 1) * pageSize : (page - 1) * pageSize + pageSize; let i=index;\">\n                                  <td class=\"text-left text-muted\"># {{i+1}}</td>\n                                  <td class=\"text-left\"> {{balance['system_transaction_id']}} </td>\n                                  <td class=\"text-left\">\n                                     <span *ngIf=\"balance['status'] == 'pending'\"\n                                        class=\"badge badge-warning\"> {{balance['status'] | uppercase}}\n                                     </span>\n                                     <span *ngIf=\"balance['status'] == 'accepted'\"\n                                        class=\"badge badge-success\"> {{balance['status'] | uppercase}}\n                                     </span>\n                                     <span *ngIf=\"balance['status'] == 'rejected'\"\n                                        class=\"badge badge-danger\"> {{balance['status'] | uppercase}}\n                                     </span>\n                                  </td>\n                                  <td class=\"text-left\"> {{balance['amount']}} </td>\n                                  <td class=\"text-left\"> {{balance['transaction_type']}} </td>\n                                  <td class=\"text-left\"> {{balance['created_datetime']*1000 | date: 'medium'}}\n                                  </td>\n                                  <td class=\"text-left\"> {{balance['update_remarks']}} </td>\n                                  <td class=\"text-left\"> {{balance['updated_datetime']*1000 | date: 'medium'}}\n                                  </td>\n                                  <td class=\"text-left text-nowrap\"> {{balance['remarks']}} </td>\n                               </tr> -->\n                            </tbody>\n                         </table>\n                      </div>\n                   </td>\n                </tr>\n             </table>\n          </div>\n          <div class=\"card-footer pb-0\">\n             <div class=\"d-flex w-100 justify-content-between\">\n                <ngb-pagination [collectionSize]=\"collectionSize\" [(page)]=\"page\" [pageSize]=\"pageSize\">\n                </ngb-pagination>\n                <select class=\"custom-select\" style=\"width: auto\" name=\"pageSize\" [(ngModel)]=\"pageSize\">\n                <option [ngValue]=\"2\">2 items per page</option>\n                <option [ngValue]=\"4\">4 items per page</option>\n                <option [ngValue]=\"6\">6 items per page</option>\n                </select>\n             </div>\n          </div>\n       </form>\n    </div>\n </div>";

