module.exports = "<div class=\"row\" #accountsDetails>\n    <div class=\"col-md-12\">\n        <div class=\"card main-card mb-6\">\n            <div class=\"card-header-tab card-header bg-dark text-white\">\n                <div class=\"card-header-title font-size-lg text-uppercase font-weight-normal\">\n                    <i class=\"header-icon fa fa-edit\"></i> \n                    {{ 'Add Currency' }}\n                </div>\n            </div>\n            <div class=\"card-body\">\n                <form [formGroup]=\"currencyConfig\" class=\"m-4\">\n                    <div class=\"position-relative row form-group\">\n                        <label for=\"currency\" class=\"col-sm-2 col-form-label\">Currency\n                            <span style=\"color: red;\">*</span>\n                        </label>\n                        <div class=\"col-sm-10\">\n                            <input formControlName=\"currency\" (keypress)=\"omitSpecialCharacters($event)\" id=\"currency\" placeholder=\"\" type=\"text\" class=\"form-control text-uppercase\" maxlength=\"3\">\n                        </div>\n                    </div>\n                    <div class=\"position-relative row form-group\">\n                        <label for=\"value\" class=\"col-sm-2 col-form-label\">Conversion Rate\n                            <span style=\"color: red;\">*</span>\n                        </label>\n                        <div class=\"col-sm-10\">\n                            <input formControlName=\"value\" type=\"number\" id=\"value\" class=\"form-control\">\n                        </div>\n                    </div>\n                    <div class=\"position-relative row form-group\">\n                       \n                            <label for=\"email\">Currency Flag <span style=\"color: red;\">*</span></label>\n                            \n                            <input type=\"file\" class=\"form-control form-control-sm nrm_input\" accept=\".png, .jpg, .jpeg\"\n                                id=\"image\" (change)=\"onFileSelected($event)\" #theFile>\n                            <label #labelImport for=\"image\">Upload Image</label>\n                            <span class=\"text-danger\">(Maximum upload file size: 1 MB)</span>\n                            <!-- <div *ngIf=\"iconImage\"><img [src]=\"getImage(iconImage)\" width=\"100\" height=\"50\"></div> -->\n                            <img *ngIf=\"imageSrc\" height=\"50\" width=\"100\" class=\"rounded\" [src]=\"imageSrc\" alt=\"logo\">\n                       </div>                 \n                    <div class=\"position-relative row form-group\">\n                        <label for=\"status\" class=\"col-sm-2 col-form-label\">Status\n                            <span style=\"color: red;\">*</span>\n                        </label>\n                        <div class=\"col-sm-10 d-flex align-items-center\">\n                        <div class=\"col-auto\">\n                            <label>\n                            <input type=\"radio\" value=\"1\" formControlName=\"status\">\n                            <span class=\"design\"></span>\n                            <span class=\"text p-2\">Active</span>\n                          </label>\n                        </div>\n                        <div class=\"col-auto\">\n                          <label>\n                            <input type=\"radio\" value=\"0\" formControlName=\"status\">\n                            <span class=\"design\"></span>\n                            <span class=\"text p-2\">Inactive</span>\n                          </label>\n                        </div>\n                        </div>\n                    </div>\n                    <div class=\"customCenter\">\n                        <button type=\"submit\" class=\"btn btn-primary\" (click)=\"onSubmit()\">Add</button>\n                        &nbsp;&nbsp;\n                        <button type=\"reset\" class=\"btn btn-primary\" (click)=\"onReset()\">Reset</button>\n                        &nbsp;&nbsp;\n                        <button type=\"button\" class=\"btn btn-primary\" routerLink=\"/settings/currencyConversion\">Back</button>\n                    </div>\n                </form>\n            </div>\n        </div>\n    </div>\n</div>";

