"use strict";
module.exports = "  <div class=\"card adminInner\" style=\"margin-top: 30px;\">\n    <div class=\"card-header mb-3\">\n      <h5>Payment Gateway Charges</h5>\n    </div>\n    <div class=\"card-body p-0\">\n        <p>Total {{respData?.length}} Records</p>\n       <div class=\"mb-3\">\n          <form [formGroup]=\"regConfig\" class=\"\">\n             <div class=\"table-responsive\">\n                <table class=\"table table-borderless table-striped table-hover\" matSort\n                   (matSortChange)=\"sortData($event)\" id=\"payment\">\n                   <thead>\n                      <tr>\n                         <th scope=\"col\" class=\"text-left text-nowrap\" *ngFor=\"let header of displayColumn;\"\n                            >\n                            {{header.value }} \n                         </th>\n                      </tr>\n                   </thead>\n                   <tbody>\n                    <tr *ngIf=\"noData\">\n                        <td colspan=\"11\">\n                            <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\"></mat-spinner>\n                        </td>\n                    </tr>\n                    <tr *ngIf=\"!noData && !respData.length\">\n                        <td colspan=\"11\">\n                            <h4 class=\"text-muted text-center\">\n                                No Data Found!\n                            </h4>\n                        </td>\n                    </tr>\n                      <ng-container *ngFor=\"let data of t.controls; let i = index\">\n                         <tr [formGroup]=\"data\" *ngIf=\"data?.get('module_type')?.value\">\n                         <td class=\"text-left text-muted\">{{i+1}}.</td>\n                        <td class=\"text-left\">{{data?.get('module_type')?.value}}</td>\n                        <td class=\"text-left\"> <div class=\"col-sm-4 d-flex align-items-center\">\n                    <div class=\"col-auto\">\n                        <label>\n                        <input type=\"radio\" value=\"percentage\" formControlName=\"fees_type\">\n                        <span class=\"design\"></span>\n                        <span class=\"text\">perc%</span>\n                      </label>\n                    </div>\n                    <div class=\"col-auto\">\n                      <label>\n                        <input type=\"radio\" value=\"plus\" formControlName=\"fees_type\">\n                        <span class=\"design\"></span>\n                        <span class=\"text\">plus+</span>\n                      </label>\n                    </div>\n                    </div> </td>\n                        <td class=\"text-left\"><input  type=\"text\" formControlName=\"fees\" placeholder=\"fees\" />  </td>\n                        <td class=\"text-left\"> <div class=\"col-sm-4 d-flex align-items-center\">\n                    <div class=\"col-auto\">\n                        <label>\n                        <input type=\"radio\" value=\"Yes\" formControlName=\"added_per_pax\">\n                        <span class=\"design\"></span>\n                        <span class=\"text\">Yes</span>\n                      </label>\n                    </div>\n                    <div class=\"col-auto\">\n                      <label>\n                        <input type=\"radio\" value=\"No\" formControlName=\"added_per_pax\">\n                        <span class=\"design\"></span>\n                        <span class=\"text\">No</span>\n                      </label>\n                    </div>\n                    </div> </td>\n                      </tr>\n                    </ng-container>\n                   </tbody>\n                </table>\n             </div>\n             <div class=\"pb-0\">\n              <button class=\"btn btn-sm btn-primary\" (click)=\"updatePaymentCharges()\">Update</button>\n              &nbsp; &nbsp;\n              <button class=\"btn btn-sm btn-secondary\" type=\"reset\" (click)=\"resetData()\">Reset</button>\n             </div>\n          </form>\n       </div>\n    </div>\n </div>";

