"use strict";
module.exports = "<div class=\"create-sub-agent-container\">\n    <div class=\"custom-table-layout mt-3\">\n        <div class=\"row\">\n            <div class=\"col-md-12 col-lg-12\">\n                <form class=\"clearfix\">\n                    <div class=\"row col-md-12 col-lg-12 m-0 p-0\">\n                        <table style=\"table-layout: fixed; width: 100%;\" id=\"active-users-report\">\n                            <tr>\n                                <td>\n                                    <div class=\"table-responsive\">\n                                        <table\n                                            class=\"align-middle mb-0 table table-borderless table-striped table-hover\"\n                                            matSort >\n                                            <thead>\n                                                <tr class=\"p-2\">\n                                                    <th scope=\"col\" class=\"text-nowrap\"\n                                                        *ngFor=\"let header of displayColumn;\"\n                                                        mat-sort-header=\"{{header.key}}\">\n                                                        {{header.value }}\n                                                    </th>\n                                                </tr>\n                                            </thead>\n                                            <tbody>\n                                                <tr *ngIf=\"noData\">\n                                                    <td colspan=\"11\">\n                                                        <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\"></mat-spinner>\n                                                    </td>\n                                                </tr>\n                                                <tr *ngIf=\"!noData && !respData.length\">\n                                                    <td colspan=\"11\">\n                                                        <h4 class=\"text-muted text-center\">\n                                                            No Data Found!\n                                                        </h4>\n                                                    </td>\n                                                </tr>\n                                                <tr class=\"p-2\"\n                                                *ngFor=\"let data of respData; let i=index;\">\n                                                <td class=\"text-left text-muted\">{{i+1}}.</td>\n                                                <td class=\"text-left\"> {{data['cityname']}}</td>\n                                                <td class=\"text-left\"> {{data['description']}}</td>\n                                                <td class=\"text-left\">\n                                                    <ul>\n                                                      <li *ngFor=\"let item of data['package_includes']\">{{item.package_includes}}</li>\n                                                    </ul>\n                                                  </td>\n                                                    <td class=\"text-left\">\n                                                        <a href=\"{{getImage(data.Banner_img)}}\" target=\"_blank\"><img width=\"100\"\n                                                                [src]=\"getImage(data.Banner_img)\" alt=\"\"></a>\n                                                    </td>\n                                                     <td class=\"text-left\">\n                                                        <select class=\"w-100 m-auto cust-select\" (change)='onStatusChange(data)'>\n                                                            <option [selected]=\"data['status'] == 0\">Inactive</option>\n                                                            <option [selected]=\"data['status'] == 1\">Active</option>\n                                                        </select>\n                                                    </td>  \n                                                    <td > \n                                                        <button class=\"btn btn-sm btn-primary\"\n                                                        (click)=\"updateContent(data)\">\n                                                            <i class=\"fa fa-edit text-nowrap\">\n                                                                {{'Update'}}\n                                                            </i>\n                                                        </button>\n                                                        \n                                                        &nbsp; &nbsp;\n                                                        <button class=\"btn btn-sm btn-primary \"  (click)=\"deleteContent(data?.id)\">\n                                                            <i class=\"fa fa-trash text-nowrap\">\n                                                                {{'Delete'}}\n                                                            </i>\n                                                        </button>\n                                                    </td>\n\n                                                </tr>\n                                            </tbody>\n                                        </table>\n                                    </div>\n                                </td>\n                            </tr>\n                        </table>\n                    </div>\n                    <div class=\"card-footer pb-0\">\n                        <div class=\"d-flex w-100 justify-content-between\">\n                            <ngb-pagination [collectionSize]=\"collectionSize\" [(page)]=\"page\" [pageSize]=\"pageSize\">\n                            </ngb-pagination>\n                        </div>\n                    </div>\n                </form>\n            </div>\n        </div>\n    </div>\n</div>\n\n\n\n\n";

