module.exports = "<div class=\"card adminInner\">\n  <div class=\"card-header mb-3\">\n    <h5>Edit City</h5>\n  </div>\n\n  <form [formGroup]=\"cityForm\" (ngSubmit)=\"onCityUpdate()\">\n<div class=\"form-row\">\n    <!-- State Dropdown -->\n     <div class=\"col-md-4\">\n      <label>Choose State</label>\n      <select class=\"form-control\" formControlName=\"state_id\">\n        <option value=\"\" disabled>Select State</option>\n        <option *ngFor=\"let state of stateList\" [value]=\"state.id\">\n          {{ state.name }}\n        </option>\n      </select>\n       <div *ngIf=\"f.state_id.touched && f.state_id.errors\">\n      <small class=\"errorMessage\">*Please select state</small>\n    </div>\n    </div>\n\n   \n\n    <!-- City Name -->\n     <div class=\"col-md-4\">\n      <label>City Name</label>\n      <input type=\"text\" class=\"form-control\" formControlName=\"city_name\">\n        <div *ngIf=\"f.city_name.touched && f.city_name.errors\">\n      <small *ngIf=\"f.city_name.errors.required\" class=\"errorMessage\">*Required</small>\n      <small *ngIf=\"f.city_name.errors.invalidString\" class=\"errorMessage\">*Numbers not allowed</small>\n      <small *ngIf=\"f.city_name.errors.startOrEndSpace\" class=\"errorMessage\">*No space at start/end</small>\n    </div>\n    </div>\n\n  \n\n    <!-- Latitude -->\n     <!-- <div class=\"col-md-4\">\n      <label>Latitude</label>\n      <input type=\"text\" class=\"form-control\" formControlName=\"latitude\">\n    </div> -->\n\n    <!-- Longitude -->\n     <!-- <div class=\"col-md-4\">\n      <label>Longitude</label>\n      <input type=\"text\" class=\"form-control\" formControlName=\"longitude\">\n    </div> -->\n <div class=\"col-md-4\">\n  <label>Status</label>\n\n  <div class=\"toggleSwitch d-flex align-items-center\">\n    \n    <mat-slide-toggle\n      [checked]=\"cityForm.get('status').value === 1\"\n      (change)=\"onStatusChange($event)\"\n    >\n    </mat-slide-toggle>\n\n    <span class=\"ml-2\">\n      {{ cityForm.get('status').value === 1 ? 'Active' : 'Inactive' }}\n    </span>\n\n  </div>\n</div>\n</div>\n    <!-- Buttons -->\n    <div class=\"saveButton mt-3\">\n      <button type=\"submit\" class=\"btn btn-primary mr-2\">Update</button>\n      <button type=\"button\" class=\"btn btn-secondary\" routerLink=\"/tour-crs/city\">\n        City List\n      </button>\n    </div>\n\n  </form>\n</div>";

