module.exports = "<div class=\"sub-agent-container custom-table-layout card row\" style=\"padding: 20px;\">\n    <div class=\"add-traveller\">\n        <div class=\"title\">\n            <h3>Add Include Master</h3>\n        </div>\n        <div class=\"custom-inline-form\">\n            <form class=\"\" [formGroup]=\"regConfig\" autocomplete=\"off\">\n\n                <div class=\"form-row\">\n\n                    <div class=\"col-6 pr-0\">\n                        <div class=\"form-group\">\n                            <label for=\"bookedBy\">Package Includes</label>\n                            <input formControlName=\"package_includes\" type=\"text\" id=\"page_title\" autocomplete=\"off\"\n                                class=\"form-control form-control-sm nrm_input\" placeholder=\"Package Includes\">\n                            <div>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"col-6 pr-0 \">\n                        <div class=\"form-group\">\n                            <label for=\"email\">Icon</label>\n                            <input type=\"file\" class=\"form-control form-control-sm nrm_input\" accept=\".png, .jpg, .jpeg\"\n                                id=\"image\" (change)=\"onFileSelected($event)\" #theFile>\n                            <label #labelImport for=\"image\">Upload Image</label>\n                            <span class=\"text-danger\">(Maximum upload file size: 1 MB)</span>\n                            <div *ngIf=\"iconImage\"><img [src]=\"getImage(iconImage)\" width=\"100\" height=\"50\"></div>\n                            <img *ngIf=\"imageSrc\" height=\"50\" width=\"100\" class=\"rounded\" [src]=\"imageSrc\" alt=\"logo\">\n                        </div>\n                    </div>\n                </div>\n                <div class=\"form-group row mb-n2\">\n                    <div class=\"col-sm-12 customCenter\">\n                        <button type=\"submit\" class=\"btn btn-sm btn-primary mr-1\" [disabled]=\"!logoUpload\"\n                            (click)=\"onSubmit()\">\n                            Submit\n                        </button>\n\n                        <button type=\"reset\" class=\"btn btn-sm btn-primary\" (click)=\"onReset()\">Reset</button>\n                    </div>\n                </div>\n            </form>\n        </div>\n    </div>\n</div>";

