/***/ 98002:
/*!****************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/transfer-crs/components/car-aminities/car-aminities-list/car-aminities-list.component.html?ngResource ***!
  \****************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card adminInner\">\n    <div class=\"card-header mb-3\">\n        <h5>{{'Car Amenity List'}}</h5>\n    </div>\n    <form>\n         <div class=\"form-group col-sm-3 p-0 mb-3 float-right has-search\">\n            Full text search:\n            <input class=\"form-control mr-3\" type=\"text\" name=\"searchTerm\" (keyup)=\"applyFilter($event.target.value)\" />\n         </div>\n       \n        <div class=\"table-responsive\">\n            <table class=\"table table-borderless table-striped table-hover\" matSort (matSortChange)=\"sortData($event)\">\n                <thead>\n                    <tr>\n                        <th scope=\"col\" class=\"text-left text-nowrap\" *ngFor=\"let header of displayColumn;\"\n                            mat-sort-header=\"{{header.key}}\">\n                            {{header.value }} </th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr *ngIf=\"noData\">\n                        <td colspan=\"11\">\n                            <mat-spinner [diameter]=\"30\" style=\"margin:0 auto;\" mode=\"indeterminate\"></mat-spinner>\n                        </td>\n                    </tr>\n                    <tr\n                        *ngFor=\"let data of respData | slice: (page - 1) * pageSize : (page - 1) * pageSize + pageSize; let i=index;\">\n                        <td class=\"text-left text-muted\">{{i+1}}.</td>\n                        <td class=\"text-left\"> {{data['amenties']}} </td>\n                        <td>\n                            <span title=\"Slide for Active/Deactive\">\n                                <mat-slide-toggle  class=\"example-margin\" [color]=\"''\"\n                                   [(ngModel)]=\"data['status']\" name=\"status{{i}}\"\n                                    (change)=\"onStatusUpdate(data, i)\">\n                                </mat-slide-toggle>\n                            </span>\n                        </td>\n                        <td class=\"text-left btncontainer\">\n                                <button  class=\"btn-primary mr-2\" (click)=\"updateRoomAmenity(data)\">{{'Update'}}</button>&nbsp;\n                                <button class=\"btn-secondary\" (click)=\"deleteRoomAmenity(data)\">{{'Delete'}}</button>\n                        </td>\n\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n        <div class=\"card-footer pb-0\">\n            <div class=\"d-flex w-100 justify-content-between\">\n                <ngb-pagination [collectionSize]=\"collectionSize\" [maxSize]=\"12\" [rotate]=\"true\" [boundaryLinks]=\"true\" [(page)]=\"page\"\n                    [pageSize]=\"pageSize\">\n                </ngb-pagination>\n                <select class=\"custom-select\" style=\"width: auto\" name=\"pageSize\" [(ngModel)]=\"pageSize\">\n                    <option [ngValue]=\"10\">10 items per page</option>\n                    <option [ngValue]=\"20\">20 items per page</option>\n                    <option [ngValue]=\"50\">50 items per page</option>\n                </select>\n            </div>\n        </div>\n    </form>\n</div>\n";

/***/ }),

