/***/ 58356:
/*!*********************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/transfer-crs/components/vehicles/combustion-master/combustion-master.component.html?ngResource ***!
  \*********************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card adminInner\">\n\n  <!-- HEADER -->\n \n    <div class=\"card-header mb-3\">\n      <h5>Combustion Master</h5>\n    </div>\n  \n\n  <!-- FORM -->\n  <div class=\"mb-3\" *ngIf=\"enabledForm\">\n    <form [formGroup]=\"form\" (ngSubmit)=\"saveText === 'Save' ? onSave() : onUpdate()\">\n\n      <div class=\"form-group row\">\n\n        <!-- TYPE -->\n        <div class=\"col-4\">\n          <label class=\"control-label\">\n            Type <span class=\"text-danger\">*</span>\n          </label>\n         \n            <input\n              type=\"text\"\n              class=\"form-control\"\n              formControlName=\"type\"\n              placeholder=\"Enter Type\"\n              [class.is-invalid]=\"form.get('type').invalid && (form.get('type').dirty || isSubmitted)\"\n            />\n\n            <div *ngIf=\"form.get('type').invalid && (form.get('type').dirty || isSubmitted)\" class=\"invalid-feedback\">\n              <span *ngIf=\"form.get('type').errors?.required\">Type is required</span>\n              <span *ngIf=\"form.get('type').errors?.pattern\">Only characters allowed</span>\n            </div>\n        \n        </div>\n\n        <!-- STATUS -->\n        <div class=\"col-3\" *ngIf=\"saveText == 'Save'\">\n          <label class=\"control-label\">Status</label>\n          \n            <mat-slide-toggle formControlName=\"status\">\n              {{ form.get('status')?.value ? 'Active' : 'Inactive' }}\n            </mat-slide-toggle>\n        \n        </div>\n        <div class=\"col-3\">\n          <!-- BUTTONS -->\n          <div class=\"saveButton\">\n            <label>&nbsp;</label>\n            <button type=\"submit\" class=\"btn-primary mr-2 save-btn\">\n              {{ saveText }}\n            </button>\n\n            <button type=\"button\" class=\"btn-secondary\" (click)=\"onCancel()\">\n              Cancel\n            </button>\n          </div>\n\n        </div>\n\n      </div>\n\n      \n\n    </form>\n  </div>\n\n\n\n<!-- TABLE -->\n<div class=\"entireScreen\">\n   <div class=\"form-group col-sm-3 p-0 mb-3 float-right has-search\">\n            Full text search:\n            <input class=\"form-control ml-0\" type=\"text\" name=\"Search\" [(ngModel)]=\"searchText\" autocomplete=\"off\"\n            placeholder=\"Search\">\n     </div>\n  <div class=\"table-responsive\">\n    <table class=\"table table-striped table-hover\">\n\n      <thead>\n        <tr>\n          <th>Sl.No</th>\n          <th>Status</th>\n          <th>Type</th>\n          <th>Action</th>\n        </tr>\n      </thead>\n\n      <tbody>\n\n        <!-- LOADER -->\n        <tr *ngIf=\"loading\">\n          <td colspan=\"4\" class=\"text-center\">\n            <mat-spinner [diameter]=\"30\"></mat-spinner>\n          </td>\n        </tr>\n\n        <!-- NO DATA -->\n        <tr *ngIf=\"!loading && !list.length\">\n          <td colspan=\"4\" class=\"text-center text-muted\">\n            No Data Found!\n          </td>\n        </tr>\n\n        <!-- DATA -->\n        <tr *ngFor=\"let item of list | filter: searchText | slice:(page-1)*pageSize:(page-1)*pageSize+pageSize; let i = index\">\n          \n          <td>{{ i + 1 }}</td>\n\n          <td>\n            <mat-slide-toggle\n              [(ngModel)]=\"item.status\"\n              (change)=\"onStatusChange($event, item.id)\">\n            </mat-slide-toggle>\n          </td>\n\n          <td>{{ item.type }}</td>\n\n          <td>\n            <button class=\"btn btn-sm btn-primary mr-2\" (click)=\"onEdit(item)\">\n              Edit\n            </button>\n\n            <button class=\"btn btn-sm btn-secondary\" (click)=\"onDelete(item.id)\">\n              Delete\n            </button>\n          </td>\n\n        </tr>\n\n      </tbody>\n    </table>\n\n    <!-- PAGINATION -->\n    <div class=\"d-flex justify-content-between\">\n      <ngb-pagination\n        [collectionSize]=\"collectionSize\"\n        [(page)]=\"page\"\n        [pageSize]=\"pageSize\">\n      </ngb-pagination>\n\n      <select class=\"custom-select w-auto\" [(ngModel)]=\"pageSize\">\n        <option [ngValue]=\"20\">20</option>\n        <option [ngValue]=\"50\">50</option>\n        <option [ngValue]=\"100\">100</option>\n      </select>\n    </div>\n\n  </div>\n</div>\n</div>\n\n";

/***/ }),

