"use strict";
module.exports = "<div class=\"sub-agent-container custom-table-layout\">\n    <div class=\"add-traveller\">\n        <div class=\"title\">\n            <h3>User Profile</h3>\n        </div>\n        <div class=\"bg-white custom-inline-form mb-4 px-3 py-4 rounded\">\n            <form class=\"\" [formGroup]=\"regConfig\" autocomplete=\"off\">\n            \n                <div class=\"form-group required row\">\n                    <label for=\"name\"class=\"required\" class=\"col-sm-2 col-form-label\">Agent Group</label>\n                    <div class=\"col-sm-4\">\n                        <input type=\"text\" class=\"form-control text-capitalize\" id=\"name\" maxlength=\"250\" \n                     (keypress)=\"omitSpecialCharacters($event)\"\n                        formControlName=\"name\">\n    \n                    </div>\n                </div>\n                <div class=\"btn-group\">\n                    <div class=\"form-group required row\">\n                        <div class=\"col-12 d-flex\">\n                            <button class=\"btnStyle\" type=\"submit\" class=\"btn btn-primary icon-btn lg mr-4\" (click)=\"onSubmit()\">Save</button>\n                            <!-- <button class=\"btnStyle\" type=\"reset\" class=\"btn btn-danger icon-btn lg\" (click)=\"onReset()\">Reset</button> -->\n                        </div>\n                    </div>\n                </div>\n                </form>\n                </div>\n                </div>\n                </div>\n";

