"use strict";
module.exports = "<div class=\"\">\n    <div class=\"\">\n        <ul\n            ngbNav\n            #tabs=\"ngbNav\"\n            class=\"nav-tabs tabs-animated custom_tab\"\n            [activeId]=\"activeIdString\"\n            (navChange)=\"beforeChange(false)\"\n        >\n            <li [ngbNavItem]=\"'add_update_b2cUser'\">\n                <a ngbNavLink>Create/Update B2C User</a>\n                <ng-template ngbNavContent>\n                    <app-create-b2c\n                        (b2cUserUpdate)=\"triggerTab($event)\">\n                    </app-create-b2c>\n                </ng-template>\n            </li>\n\n            <li [ngbNavItem]=\"'b2cUsers_list'\">\n                <a ngbNavLink>B2C Users List</a>\n                <ng-template ngbNavContent>\n                    <app-manage-list\n                        (b2cUserUpdate)=\"triggerTab($event)\">\n                    </app-manage-list>\n                </ng-template>\n            </li>\n        </ul>\n\n        <div [ngbNavOutlet]=\"tabs\"></div>\n    </div>\n</div>";

