"use strict";
module.exports = "<!-- <p>logged-in-users works!</p> -->\n<div class=\"card mb-3\">\n    <div class=\"card-header-tab card-header\">\n        <div class=\"card-header-title font-size-lg text-capitalize font-weight-normal\">\n            <i class=\"header-icon lnr-laptop-phone mr-3 text-muted opacity-6\"> </i>\n            {{'Logged In Users'}}\n        </div>\n    </div>\n    <div class=\"table-responsive\">\n        <table class=\"align-middle mb-0 table table-borderless table-striped table-hover\">\n            <thead>\n                <tr class=\"p-2\">\n                    <th class=\"text-left text-nowrap\" *ngFor=\"let header of displayedColumns;\">\n                        {{header}}\n                    </th>\n                </tr>\n            </thead>\n            <tbody>\n                <tr class=\"p-2\" *ngFor=\"let user of loggedInUsers; let i=index;\">\n                    <td class=\"text-left text-muted\">{{i+1}}.</td>\n                    <td>\n                        <div class=\"widget-content p-0\">\n                            <div class=\"widget-content-wrapper\">\n                                <div class=\"widget-content-left mr-3\">\n                                    <div class=\"widget-content-left\">\n                                        <img height=\"50\" width=\"50\" class=\"rounded\"\n                                            [src]=\"user['image']\" alt=\"\">\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </td>\n                    <td class=\"text-left\"> {{user['first_name'] +' '+ user['last_name']}} </td>\n                    <td class=\"text-left\"> {{user['phone'] +'-'+ user['email']}} </td>\n                    <td class=\"text-left\"> {{user['user_type']}} </td>\n                    <td class=\"text-left\"> {{user['login_ip']}} </td>\n                    <td class=\"text-left\"> {{user['login_time']}} </td>\n                </tr>\n                <tr *ngIf=\"!loggedInUsers.length\">\n                    <td colspan=\"7\" class=\"text-center\">\n                        <mat-spinner [diameter]=\"30\" mode=\"indeterminate\" style=\"margin: 0 auto;\"></mat-spinner>\n                        No Data Found\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n</div>";

