"use strict";
module.exports = "<div class=\"card main-card mb-3\">\n    <div class=\"card-header\">\n        User Details\n    </div>\n    <div class=\"card-body\">\n        <table class=\"table\">\n            <tbody>\n                <tr>\n                    <th scope=\"row\">User ID</th>\n                    <td scope=\"row\">{{ 'TM1561640281' }}</td>\n                    <th scope=\"row\">Name</th>\n                    <td scope=\"row\">puja shruthi</td>\n                </tr>\n                <tr>\n                    <th scope=\"row\">Email</th>\n                    <td scope=\"row\">testingdhjb@gmail.com</td>\n                    <th scope=\"row\">Phone</th>\n                    <td scope=\"row\">8987654321</td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n</div>\n<div class=\"card main-card mb-3\">\n    <div class=\"card-body\">\n        <table class=\"table\">\n            <thead>\n                <th scope=\"col\">SLNo</th>\n                <th scope=\"col\">Privilege Description</th>\n                <th scope=\"col\">\n                    Select\n                    <button *ngIf=\"!allSelected\" (click)=\"selectAll(1)\" class=\"btn btn-primary btn-sm\">All</button>\n                    <button *ngIf=\"allSelected\" (click)=\"selectAll(0)\" class=\"btn btn-secondary btn-sm\">Reset</button>\n                </th>\n            </thead>\n            <tbody>\n                <tr *ngFor=\"let p of privileges; let i = index;\">\n                        <td scope=\"row\">{{ i + 1 }}</td>\n                        <td>{{ p.description }}<input type=\"hidden\"></td>\n                        <td><input type=\"checkbox\" [checked]=\"p.enabled\" [(ngModel)]=\"p.enabled\"/></td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n    <div class=\"card-footer\">\n        <button (click)=\"updatePrivileges()\" class=\"btn btn-primary\">Save </button>\n        &nbsp; &nbsp;\n        <button (click)=\"selectAll(0)\" class=\"btn btn-secondary\">Reset </button>\n    </div>\n</div>";

