/***/ 80488:
/*!*******************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/wellness-crs/components/facilities/facilities-list/facilities-list.component.html?ngResource ***!
  \*******************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<!-- Filter Section -->\n<div class=\"card adminInner\">\n\n    <div class=\"card-header mb-3\">\n        <h5>Facilities List</h5>\n    </div>\n\n    <form *ngIf=\"showFilters\">\n        <div class=\"row\">\n            <div class=\"col-md-12 mb-3\">\n                <label>Facilities</label>\n                <input type=\"text\" class=\"form-control form-control-sm\" placeholder=\"Facilities List\">\n            </div>\n        </div>\n\n        <div class=\"btncontainer\">\n            <button type=\"button\" class=\"btn btn-primary btn-sm mr-2\">Search</button>\n            <button type=\"button\" class=\"btn btn-secondary btn-sm\">Reset</button>\n        </div>\n    </form>\n\n</div>\n\n\n<!-- Table Section -->\n<div class=\"card adminInner mt-3\">\n\n    <div class=\"d-flex justify-content-between align-items-center mb-3\">\n        <div>\n            <button class=\"btn btn-primary btn-sm mr-2\">Export</button>\n            <button class=\"btn btn-secondary btn-sm\" (click)=\"showFilters = !showFilters\">Filter</button>\n        </div>\n\n        <div style=\"width:250px;\">\n            <small>Full Text Search</small>\n            <input type=\"text\" class=\"form-control form-control-sm\"  [(ngModel)]=\"searchText\"\n        (input)=\"filterFacilities()\">\n        </div>\n    </div>\n\n    <!-- <small class=\"text-muted\">25 Therapy Types Found.</small> -->\n\n    <div class=\"wrapper1 mt-3\" id=\"notifications-list\" (scroll)=\"scrollTwo.scrollLeft = scrollOne.scrollLeft\" #scrollOne>\n        <div class=\"div1\"></div>\n    </div>\n\n    <div class=\"wrapper2\" #scrollTwo (scroll)=\"scrollOne.scrollLeft = scrollTwo.scrollLeft\">\n        <div class=\"div2 invisible-scrollbar\">\n            <div class=\"table-responsive\">\n                <table class=\"table table-striped table-hover\">\n\n            <thead>\n                <tr>\n                    <th>Sl. No</th>\n                    <th>Status</th>\n                    <th>Facilities</th>\n                    <th>Actions</th>\n                </tr>\n            </thead>\n\n            <tbody>\n\n                <tr *ngFor=\"let facility of filteredFacilitiesList; let i = index\">\n                    <td>{{ i + 1 }}</td>\n                    <td>\n                        <label class=\"switch\">\n                            <input type=\"checkbox\" [checked]=\"facility.status === '1' || facility.status === 1 ? true : false\"\n                            (change)=\"onStatusChange($event, facility)\">\n                            <span class=\"slider round\"></span>\n                        </label>\n                    </td>\n                    <td>{{ facility.name }}</td>\n\n                    <td class=\"action-btn\">\n                        <button class=\"btn btn-sm btn-primary mr-2\" type=\"button\" (click)=\"onUpdate(facility)\">Update</button>\n                        <button class=\"btn btn-sm btn-secondary\" type=\"button\" (click)=\"onDelete(facility.id)\">Delete</button>\n                    </td>\n                </tr>\n\n                \n\n            </tbody>\n\n                </table>\n            </div>\n        </div>\n    </div>\n\n\n\n</div>\n";

/***/ }),

