/***/ 14804:
/*!*******************************************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/wellness-crs/components/health-goals-condition/add-update-health-goal-type/add-update-health-goal-type.component.html?ngResource ***!
  \*******************************************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card adminInner\">\n    <div class=\"card-header\">\n        <h5>Add/ Edit Health Goals/Conditions-Type</h5>\n    </div>\n\n    <form class=\"needs-validation pt-3\" novalidate>\n        <div class=\"card-body p-0\">\n            <fieldset>\n                <div class=\"row\">\n\n                    <!-- Stay Type Name -->\n                     <form [formGroup]=\"addUpdateHealthGoalTypeListForm\" class=\"w-100\"\n                     (ngSubmit)=\"onSubmit()\">\n                    <div class=\"col-md-12 pr-0 mb-4\">\n                        <label class=\"control-label\" for=\"hotel_type_name\">\n                            Health Goals/Conditions-Type\n                            <span class=\"text-danger\">*</span>\n                        </label>\n\n                        <input type=\"text\" \n                            id=\"hotel_type_name\"\n                            name=\"hotel_type_name\"\n                            formControlName=\"name\"\n                            placeholder=\"Health Goals/Conditions-Type\"\n                            class=\"form-control\"\n                            required />\n\n                        <div class=\"invalid-feedback\"  *ngIf=\"addUpdateHealthGoalTypeListForm.get('name').invalid && submitted\">\n                           Health Goals/Conditions-Type is required\n                        </div>\n                    </div>\n\n                    <div class=\"col-md-12 pr-0 mb-4\">\n                        <label class=\"control-label\" for=\"description\">\n                            Description\n                            <span class=\"text-danger\">*</span>\n                        </label>\n\n                        <textarea\n                            id=\"description\"\n                            name=\"description\"\n                            formControlName=\"description\"\n                            placeholder=\"Enter Description\"\n                            class=\"form-control\"\n                            rows=\"3\"\n                            required></textarea>\n\n                        <div class=\"invalid-feedback\" *ngIf=\"addUpdateHealthGoalTypeListForm.get('description').invalid && submitted\">\n                           Description is required\n                        </div>\n                    </div>\n\n                    <div class=\"col-md-12 pr-0 mb-4\">\n                        <label class=\"control-label\">\n                            Health Goals/Conditions Image\n                            <span class=\"text-danger\" *ngIf=\"!isEdit\">*</span>\n                        </label>\n\n                        <div class=\"mb-2\" *ngIf=\"imageSrc\">\n                            <img [src]=\"imageSrc\" height=\"80\" width=\"120\" class=\"rounded\">\n                        </div>\n\n                        <input type=\"file\"\n                            accept=\".jpeg,.jpg,.png,.svg,.webp\"\n                            class=\"form-control\"\n                            (change)=\"previewImage($event)\" />\n\n                        <small class=\"text-muted\">\n                            Only JPG, JPEG, PNG, SVG, and WEBP formats up to 500 KB are allowed.\n                        </small>\n                    </div>\n                    \n                    <!-- Status -->\n                   <div class=\"col-md-12\">\n                    <label class=\"control-label\">\n                        Status\n                        <span class=\"text-danger\">*</span>\n                    </label>\n                   \n\n                    <label class=\"switch\">\n                        <input type=\"checkbox\" name=\"status\" formControlName=\"status\">\n                        <span class=\"slider round\"></span>\n                    </label>\n                   </div>\n\n                    <!-- Buttons -->\n                    <div class=\"col-md-12 mt-4\">\n                        <button type=\"submit\" class=\"btn btn-primary\">Save</button>\n                        &nbsp;&nbsp;\n                        <button type=\"reset\" class=\"btn btn-secondary\" (click)=\"resetForm()\">Reset</button>\n                    </div>\n\n                    </form>\n                </div>\n            </fieldset>\n        </div>\n    </form>\n</div>\n\n";

/***/ }),

