     <!-- Buttons -->\n                    <div class=\"col-md-12 mt-4\">\n                        <button type=\"submit\" class=\"btn btn-primary\">Save</button>\n                        &nbsp;&nbsp;\n                        <button type=\"reset\" class=\"btn btn-secondary\">Reset</button>\n                    </div>\n                    </form>\n\n                </div>\n            </fieldset>\n        </div>\n    </form>\n</div>\n\n\n";

