/***/ 17131:
/*!******************************************************************************************************************************************************!*\
  !*** ./projects/supervision/src/app/modules/wellness-crs/components/patanjali-wellness-gallery/patanjali-wellness-gallery.component.html?ngResource ***!
  \******************************************************************************************************************************************************/
/***/ ((module) => {

"use strict";
module.exports = "<div class=\"card patanjali-gallery\">\n  <div class=\"card-header d-flex justify-content-between align-items-center\">\n    <div>\n      <h5 class=\"mb-0\">Patanjali Wellness Gallery</h5>\n      <small class=\"text-muted\">Gallery upload ID: {{ galleryId }}</small>\n    </div>\n  </div>\n\n  <div class=\"card-body\">\n    <form (ngSubmit)=\"uploadGallery()\" class=\"mb-4\">\n      <div class=\"form-group\">\n        <label for=\"uploadGallery\"><b>Upload Gallery</b></label>\n        <input\n          #galleryInput\n          type=\"file\"\n          id=\"uploadGallery\"\n          class=\"form-control-file\"\n          multiple\n          accept=\".png,.jpg,.jpeg,.webp,.svg\"\n          (change)=\"onGallerySelect($event)\">\n        <small class=\"text-danger\">Only JPG, JPEG, PNG, SVG, and WEBP images up to 1 MB are allowed.</small>\n      </div>\n      <div class=\"form-group form-check\">\n        <input\n          type=\"checkbox\"\n          id=\"isTrending\"\n          class=\"form-check-input\"\n          name=\"is_trending\"\n          [(ngModel)]=\"isTrending\">\n        <label class=\"form-check-label\" for=\"isTrending\">Is Trending</label>\n      </div>\n\n      <button type=\"submit\" class=\"btn btn-sm btn-success\" [disabled]=\"loading || !selectedFiles.length\">\n        Upload Images\n      </button>\n    </form>\n\n    <div *ngIf=\"editingImage\" class=\"edit-panel mb-4\">\n      <h6 class=\"mb-3\">Update Image: {{ getImageName(editingImage) }}</h6>\n      <div class=\"d-flex align-items-center flex-wrap\">\n        <img [src]=\"getImageUrl(editingImage)\" class=\"edit-preview mr-3 mb-2\" alt=\"Selected gallery image\">\n        <div>\n          <input\n            #updateInput\n            type=\"file\"\n            class=\"form-control-file mb-2\"\n            accept=\".png,.jpg,.jpeg,.webp,.svg\"\n            (change)=\"onUpdateSelect($event)\">\n          <div class=\"form-check mb-2\">\n            <input\n              type=\"checkbox\"\n              id=\"updateIsTrending\"\n              class=\"form-check-input\"\n              name=\"update_is_trending\"\n              [(ngModel)]=\"isTrending\">\n            <label class=\"form-check-label\" for=\"updateIsTrending\">Is Trending</label>\n          </div>\n          <button type=\"button\" class=\"btn btn-sm btn-primary mr-2\" [disabled]=\"loading\" (click)=\"updateImage()\">\n            Update\n          </button>\n          <button type=\"button\" class=\"btn btn-sm btn-secondary\" (click)=\"cancelEdit()\">\n            Cancel\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"table-responsive\">\n      <table class=\"table table-borderless table-striped table-hover\">\n        <thead>\n          <tr>\n            <th>SI No.</th>\n            <th>Image</th>\n            <th>File</th>\n            <th>Trending</th>\n            <th class=\"text-right\">Actions</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr *ngIf=\"!galleryImages.length\">\n            <td colspan=\"5\" class=\"text-center text-muted\">\n              No gallery images found.\n            </td>\n          </tr>\n          <tr *ngFor=\"let image of galleryImages; let i = index\">\n            <td>{{ i + 1 }}.</td>\n            <td>\n              <a [href]=\"getImageUrl(image)\" target=\"_blank\">\n                <img [src]=\"getImageUrl(image)\" class=\"gallery-thumb\" alt=\"Gallery image\">\n              </a>\n            </td>\n            <td>{{ getImageName(image) }}</td>\n            <td>{{ isTrending ? 'True' : 'False' }}</td>\n            <td class=\"text-right\">\n              <button type=\"button\" class=\"btn btn-sm btn-primary mr-2\" (click)=\"editImage(image, i)\">\n                Edit\n              </button>\n              <button type=\"button\" class=\"btn btn-sm btn-primary\" [disabled]=\"loading\" (click)=\"deleteImage(image, i)\">\n                Delete\n              </button>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n</div>\n";

/***/ }),

