"use strict";
module.exports = "<ul ngbNav #tabs=\"ngbNav\" class=\"tabs-animated custom_tab crs-tab-ui\" [(activeId)]=\"activeIdString\" (navChange)=\"onTabSelected($event)\">\n\n  <!-- Tab 1 -->\n  <li [ngbNavItem]=\"'list_wellness'\">\n\n    <a ngbNavLink>\n      <span >Wellness Centre List</span>\n    </a>\n\n    <ng-template ngbNavContent>\n      <app-wellness-list (toUpdate)=\"triggerTab($event)\"></app-wellness-list>\n      </ng-template>\n\n  </li>\n\n  <!-- Tab 2 -->\n  <li [ngbNavItem]=\"'add_wellness'\">\n\n    <a ngbNavLink>\n      <span>Add / Edit Wellness Centre</span>\n    </a>\n\n    <ng-template ngbNavContent>\n      <app-add-update-wellness (someEvent)=\"triggerTab($event)\" [selected]=\"selected\" [wellnessOne]=\"wellnessData\"></app-add-update-wellness>\n    </ng-template>\n    \n  </li> \n\n</ul>\n\n<div [ngbNavOutlet]=\"tabs\"></div>";

