module.exports = "<div class=\"d-flex\">\n    <div class=\"header-btn-lg pr-0\">\n        <div class=\"widget-content p-0\">\n            <div class=\"widget-content-wrapper\">\n                <div class=\"widget-content-left\">\n                    <div class=\"btn-group\" ngbDropdown placement=\"bottom-right\">\n                        <button type=\"button\" class=\"btn btn-link p-0 mr-2\" ngbDropdownToggle>\n                            <span>\n                                <div class=\"icon-wrapper icon-wrapper-alt rounded-circle\">\n                                    <i class=\"far fa-user\"></i>\n                                    <!-- <img width=\"42\" [src]=\"imageURL\" alt=\"\" class=\"rounded-circle\"> -->\n                                </div>\n                            </span>\n                        </button>\n                        <div class=\"dropdown-menu-lg\" ngbDropdownMenu>\n                            <div class=\"dropdown-menu-header\">\n                                <div class=\"dropdown-menu-header-inner bg-info\">\n                                    <div class=\"menu-header-image opacity-2 dd-header-bg-6\"></div>\n                                    <div class=\"menu-header-content text-left\">\n                                        <div class=\"widget-content p-0\">\n                                            <div class=\"widget-content-wrapper\">\n                                                <div class=\"widget-content-left mr-3\">\n                                                    <i class=\"far fa-user\"></i>\n                                                    <!-- <img width=\"42\" [src]=\"imageURL\" alt=\"\" class=\"rounded-circle\"> -->\n                                                </div>\n                                                <div class=\"widget-content-left\">\n                                                    <div  class=\"widget-heading\" *ngIf=\"currentUser.auth_role_id != 6 && currentUser.auth_role_id != 3 && currentUser.auth_role_id != 7\">{{'Super Admin'}}</div>\n                                                    <div class=\"widget-heading text-uppercase\" *ngIf=\"currentUser.auth_role_id == 6\">{{'Supplier'}}: {{currentUser?.business_name}}</div>\n                                                    <div class=\"widget-heading\" *ngIf=\"currentUser.auth_role_id == 3\">{{'Sub Admin'}}</div>\n                                                    <div class=\"widget-heading text-uppercase\" *ngIf=\"currentUser.auth_role_id == 7\">{{'DMC'}}: {{currentUser?.business_name}}</div>\n                                                    <div class=\"widget-subheading opacity-8\">{{'User:'}} {{currentUser?.first_name + ' '+\n                                                        currentUser?.last_name}} - {{currentUser?.uuid}}</div>\n                                                </div>\n                                                <div class=\"widget-content-right mr-2\">\n                                                    <button class=\"btn-pill btn-shadow btn-shine btn btn-focus\"\n                                                        (click)=\"onLogout()\">Logout</button>\n                                                </div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"scroll-area-xs\">\n                                <perfect-scrollbar [autoPropagation]=\"true\">\n                                    <ul class=\"nav flex-column\">\n                                        <!-- <li class=\"nav-item-header nav-item\">Activity</li> -->\n                                        <li class=\"nav-item\">\n                                            <a routerLink=\"/user/admin-profile\" class=\"nav-link\">\n                                                Update Profile\n                                            </a>\n                                        </li>\n                                        <li class=\"nav-item\"><a routerLink=\"/user/change-password\"\n                                                class=\"nav-link\">Change Password</a></li>\n                                        <!-- <li class=\"nav-item-header nav-item\">\n                                            My Account\n                                        </li> -->\n                                        <!-- <li class=\"nav-item\">\n                                            <a routerLink=\"/settings/b2cPromocode\" class=\"nav-link\">\n                                                Settings\n                                                <div class=\"ml-auto badge badge-success\">\n                                                    New\n                                                </div>\n                                            </a>\n                                        </li> -->\n                                        <!-- <li class=\"nav-item\">\n                                            <a routerLink=\"/settings/error-event-logs\" class=\"nav-link\">\n                                                Logs\n                                            </a>\n                                        </li> -->\n                                    </ul>\n                                </perfect-scrollbar>\n                            </div>\n                            <ul class=\"nav flex-column\">\n                                <li class=\"nav-item-divider mb-0 nav-item\"></li>\n                            </ul>\n                            <div *ngIf=\"showUser\" class=\"grid-menu grid-menu-2col overflow-hidden\">\n                                <div class=\"no-gutters row\">\n                                    <div class=\"col-sm-6\">\n                                        <button routerLink=\"/bank/accountDetails\"\n                                            class=\"btn-icon-vertical btn-transition btn-transition-alt pt-2 pb-2 btn btn-outline-warning\">\n                                            <i class=\"pe-7s-culture icon-gradient bg-amy-crisp btn-icon-wrapper mb-2\"></i>\n                                            Bank Details\n                                        </button>\n                                    </div>\n                                    <div class=\"col-sm-6\">\n                                        <button routerLink=\"/agentCallBackSupport\"\n                                            class=\"btn-icon-vertical btn-transition btn-transition-alt pt-2 pb-2 btn btn-outline-danger\">\n                                            <i\n                                                class=\"pe-7s-ticket icon-gradient bg-love-kiss btn-icon-wrapper mb-2\"></i>\n                                            <b>Support Tickets</b>\n                                        </button>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <div class=\"widget-content-left ml-3 header-user-info\">\n                    <div class=\"widget-heading\">{{currentUser?.first_name + ' '+ currentUser?.last_name}}</div>\n                    <div *ngIf=\"currentUser.auth_role_id != 6 && currentUser.auth_role_id != 3 && currentUser.auth_role_id != 7\" class=\"widget-subheading\">{{'Super Admin'}}</div>\n                    <div *ngIf=\"currentUser.auth_role_id == 6\"class=\"widget-subheading\">{{'User: '}} {{currentUser?.uuid}}</div>\n                    <div *ngIf=\"currentUser.auth_role_id == 3\"class=\"widget-subheading\">{{'Sub Admin'}}</div>\n                    <div *ngIf=\"currentUser.auth_role_id == 7\"class=\"widget-subheading\">{{'User: '}} {{currentUser?.uuid}}</div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>";

