"use strict";
module.exports = "<div [class]=\"'app-header header-shadow ' + (config$ | async).headerTheme\">\n  <!-- <a routerLink=\"/\"><img width=\"120\" height=\"60\" [src]=\"getImage(loggedInUser.image)\" alt=\"HeaderLogo\"></a> -->\n  <div class=\"app-header__content\">\n    <div class=\"app-header-left\">\n      <app-mega-menu></app-mega-menu>\n    </div>\n    <div class=\"app-header-right\">\n      <div *ngIf=\"showUser\">\n      <app-dots></app-dots>\n      </div>\n      <span *ngIf=\"loggedInUser?.auth_role_id===7\">Currency: <label>{{loggedInUser?.currency ? loggedInUser?.currency : 'GBP'}}</label> </span>\n      <app-user-box></app-user-box>\n    </div>\n  </div>\n  <div class=\"app-header__mobile-menu\">\n    <button type=\"button\" class=\"hamburger close-sidebar-btn hamburger--elastic\"\n            [ngClass]=\"{'is-active' : globals.toggleSidebarMobile}\" (click)=\"toggleSidebarMobile()\">\n        <span class=\"hamburger-box\">\n            <span class=\"hamburger-inner\"></span>\n        </span>\n    </button>\n  </div>\n  <div class=\"app-header__menu\">\n    <span>\n        <button class=\"btn-icon btn-icon-only btn btn-primary\" [ngClass]=\"{'is-active' : globals.toggleHeaderMobile}\"\n                (click)=\"toggleHeaderMobile()\">\n            <div class=\"btn-icon-wrapper\">\n                  <fa-icon [icon]=\"faEllipsisV\"></fa-icon>\n            </div>\n        </button>\n    </span>\n  </div>\n</div>\n";

